-- ===== 20261022001300_room_title_is_number.sql =====
-- Rooms are identified by their number only; the title column stays for compatibility and always mirrors it.
create or replace function public.rooms_title_from_number()
returns trigger
language plpgsql
set search_path = public
as $$
begin
  new.title := 'Room ' || new.global_id;
  return new;
end;
$$;

drop trigger if exists rooms_title_from_number on public.rooms;
create trigger rooms_title_from_number
  before insert or update of global_id, title on public.rooms
  for each row execute function public.rooms_title_from_number();

update public.rooms set title = 'Room ' || global_id where title is distinct from 'Room ' || global_id;

-- ===== 20261022001400_members_moderation_chat_seen.sql =====
-- Membership lifecycle, moderation and chat read state.
--  * "Leave" really leaves: the membership is removed and coming back needs the code / invitation again
--    (the owner keeps their place).
--  * Members who stay offline for 5 minutes drop out of the participant list on their own.
--  * The owner can kick (they may come back) and ban (they may not) members.
--  * Chat read state ("have seen"): each member's last seen message, unread counter, read receipts.

-- ---------------------------------------------------------------------------
-- Tables
-- ---------------------------------------------------------------------------

create table public.room_bans (
  room_id uuid not null references public.rooms (id) on delete cascade,
  user_id uuid not null references public.profiles (id) on delete cascade,
  banned_at timestamptz not null default now(),
  primary key (room_id, user_id)
);
alter table public.room_bans enable row level security;
revoke all on public.room_bans from anon, authenticated;

create table public.chat_seen (
  room_id uuid not null references public.rooms (id) on delete cascade,
  user_id uuid not null references public.profiles (id) on delete cascade,
  last_seen_message_id uuid,
  last_seen_at timestamptz not null default now(),
  primary key (room_id, user_id)
);
alter table public.chat_seen enable row level security;
revoke all on public.chat_seen from anon, authenticated;

-- ---------------------------------------------------------------------------
-- Removing a member (used by leave, kick, ban and the offline sweep)
-- ---------------------------------------------------------------------------

create function public.remove_member(p_room_id uuid, p_user uuid) returns void
language plpgsql security definer set search_path = public
as $$
begin
  delete from public.member_activity where room_id = p_room_id and user_id = p_user;
  delete from public.chat_seen where room_id = p_room_id and user_id = p_user;
  update public.playback_state set buffering = buffering - p_user::text
    where room_id = p_room_id and buffering ? p_user::text;
  delete from public.room_members where room_id = p_room_id and user_id = p_user and role <> 'owner';
end $$;
revoke execute on function public.remove_member(uuid, uuid) from public, anon, authenticated;

-- Leaving: the owner only frees their seat; everyone else leaves the room completely.
create or replace function public.leave_room(p_room_id uuid) returns void
language plpgsql security definer set search_path = public
as $$
declare v_uid uuid := public.require_uid();
begin
  if exists (select 1 from public.rooms where id = p_room_id and owner_id = v_uid) then
    update public.member_activity set last_active_at = to_timestamp(0)
      where room_id = p_room_id and user_id = v_uid;
  else
    perform public.remove_member(p_room_id, v_uid);
  end if;
end $$;

-- Members who have not shown a sign of life for 5 minutes are dropped from the list.
create function public.drop_offline_members(p_max_idle interval default interval '5 minutes') returns integer
language plpgsql security definer set search_path = public
as $$
declare
  v_count integer := 0;
  v_row record;
begin
  for v_row in
    select m.room_id, m.user_id
    from public.room_members m
    join public.rooms r on r.id = m.room_id and r.status = 'active'
    left join public.member_activity a on a.room_id = m.room_id and a.user_id = m.user_id
    where m.role <> 'owner'
      and coalesce(a.last_active_at, m.joined_at) < now() - p_max_idle
  loop
    perform public.remove_member(v_row.room_id, v_row.user_id);
    v_count := v_count + 1;
  end loop;
  return v_count;
end $$;
revoke execute on function public.drop_offline_members(interval) from public, anon, authenticated;

do $$
begin
  if to_regclass('cron.job') is not null then
    perform cron.schedule(
      'omioroom-drop-offline-members',
      '* * * * *',
      $job$ select public.drop_offline_members(interval '5 minutes') $job$
    );
  end if;
exception when others then
  raise notice 'could not schedule cron job: %', sqlerrm;
end $$;

-- ---------------------------------------------------------------------------
-- Kick / ban / unban (owner only)
-- ---------------------------------------------------------------------------

create function public.kick_member(p_room_id uuid, p_user_id uuid) returns void
language plpgsql security definer set search_path = public
as $$
declare
  v_uid uuid := public.require_uid();
  v_room public.rooms := public.owned_active_room(p_room_id, v_uid);
begin
  if p_user_id is null or p_user_id = v_uid or p_user_id = v_room.owner_id then
    raise exception 'INVALID_PAYLOAD';
  end if;
  perform public.remove_member(p_room_id, p_user_id);
end $$;

create function public.ban_member(p_room_id uuid, p_user_id uuid) returns void
language plpgsql security definer set search_path = public
as $$
declare
  v_uid uuid := public.require_uid();
  v_room public.rooms := public.owned_active_room(p_room_id, v_uid);
begin
  if p_user_id is null or p_user_id = v_uid or p_user_id = v_room.owner_id then
    raise exception 'INVALID_PAYLOAD';
  end if;
  insert into public.room_bans (room_id, user_id) values (p_room_id, p_user_id) on conflict do nothing;
  perform public.remove_member(p_room_id, p_user_id);
end $$;

create function public.unban_member(p_room_id uuid, p_user_id uuid) returns void
language plpgsql security definer set search_path = public
as $$
declare
  v_uid uuid := public.require_uid();
  v_room public.rooms := public.owned_active_room(p_room_id, v_uid);
begin
  delete from public.room_bans where room_id = p_room_id and user_id = p_user_id;
end $$;

-- ---------------------------------------------------------------------------
-- Chat read state
-- ---------------------------------------------------------------------------

create function public.mark_chat_seen(p_room_id uuid, p_message_id uuid) returns void
language plpgsql security definer set search_path = public
as $$
declare
  v_uid uuid := public.require_uid();
  v_at timestamptz;
begin
  perform public.assert_active_member(p_room_id, v_uid);
  perform public.check_rate(v_uid, 'chat_seen', 60, interval '10 seconds');
  select created_at into v_at from public.chat_messages where id = p_message_id and room_id = p_room_id;
  if v_at is null then
    return;
  end if;
  insert into public.chat_seen (room_id, user_id, last_seen_message_id, last_seen_at)
  values (p_room_id, v_uid, p_message_id, v_at)
  on conflict (room_id, user_id) do update
    set last_seen_message_id = excluded.last_seen_message_id, last_seen_at = excluded.last_seen_at
    where public.chat_seen.last_seen_at < excluded.last_seen_at;
end $$;

-- ---------------------------------------------------------------------------
-- Join: banned users are refused; a newcomer starts with an empty unread counter
-- ---------------------------------------------------------------------------

create or replace function public.join_room(p_global_id text, p_private_code text default null) returns jsonb
language plpgsql security definer set search_path = public
as $$
declare
  v_uid uuid := public.require_uid();
  v_room public.rooms;
  v_member public.room_members;
  v_secret public.room_secrets;
  v_active integer;
begin
  perform public.check_rate(v_uid, 'join_room', 15, interval '60 seconds');

  if p_global_id is null or p_global_id !~ '^[0-9]{6}$' then
    return jsonb_build_object('error', 'INVALID_PAYLOAD');
  end if;

  select * into v_room from public.rooms where global_id = p_global_id and status = 'active';
  if v_room.id is null then
    return jsonb_build_object('error', 'ROOM_NOT_FOUND');
  end if;

  if exists (select 1 from public.room_bans where room_id = v_room.id and user_id = v_uid) then
    return jsonb_build_object('error', 'BANNED');
  end if;

  select * into v_member from public.room_members where room_id = v_room.id and user_id = v_uid;

  if v_room.visibility = 'private' and v_room.owner_id <> v_uid and v_member.user_id is null then
    if p_private_code is null or trim(p_private_code) = '' then
      return jsonb_build_object('error', 'PRIVATE_CODE_REQUIRED');
    end if;
    select * into v_secret from public.room_secrets where room_id = v_room.id;
    if v_secret.room_id is null
       or v_secret.revoked_at is not null
       or v_secret.secret_hash <> public.hash_secret(trim(p_private_code)) then
      return jsonb_build_object('error', 'INVALID_PRIVATE_CODE');
    end if;
  end if;

  select count(*) into v_active
    from public.member_activity
    where room_id = v_room.id and user_id <> v_uid and last_active_at > public.seat_active_cutoff();
  if v_active >= v_room.max_participants then
    return jsonb_build_object('error', 'ROOM_FULL');
  end if;

  if v_member.user_id is null then
    insert into public.room_members (room_id, user_id, role) values (v_room.id, v_uid, 'member');
    insert into public.chat_seen (room_id, user_id) values (v_room.id, v_uid) on conflict do nothing;
  end if;
  perform public.mark_active(v_room.id, v_uid);

  return public.build_snapshot(v_room.id, v_uid);
end $$;

-- ---------------------------------------------------------------------------
-- Snapshot: read receipts, unread counter, banned list (owner)
-- ---------------------------------------------------------------------------

create or replace function public.build_snapshot(p_room_id uuid, p_viewer uuid) returns jsonb
language plpgsql stable security definer set search_path = public
as $$
declare
  v_room public.rooms;
  v_state public.playback_state;
  v_seen timestamptz;
begin
  select * into v_room from public.rooms where id = p_room_id;
  select * into v_state from public.playback_state where room_id = p_room_id;
  select last_seen_at into v_seen from public.chat_seen where room_id = p_room_id and user_id = p_viewer;
  return jsonb_build_object(
    'room', public.room_dto(v_room),
    'isOwner', v_room.owner_id = p_viewer,
    'canControl', public.can_control_playback(p_room_id, p_viewer),
    'participants', coalesce((
      select jsonb_agg(jsonb_build_object(
        'userId', m.user_id,
        'displayName', p.display_name,
        'role', m.role,
        'canControl', m.role = 'owner' or m.can_control,
        'joinedAt', m.joined_at,
        'isOnline', coalesce(a.last_active_at > public.seat_active_cutoff(), false),
        'chatSeenAt', s.last_seen_at
      ) order by m.joined_at)
      from public.room_members m
      join public.profiles p on p.id = m.user_id
      left join public.member_activity a on a.room_id = m.room_id and a.user_id = m.user_id
      left join public.chat_seen s on s.room_id = m.room_id and s.user_id = m.user_id
      where m.room_id = p_room_id
    ), '[]'::jsonb),
    'unreadCount', (
      select count(*) from public.chat_messages c
      where c.room_id = p_room_id and c.sender_id <> p_viewer and c.created_at > coalesce(v_seen, '-infinity'::timestamptz)
    ),
    'bannedUsers', case when v_room.owner_id = p_viewer then coalesce((
      select jsonb_agg(jsonb_build_object('userId', b.user_id, 'displayName', p.display_name) order by b.banned_at)
      from public.room_bans b join public.profiles p on p.id = b.user_id
      where b.room_id = p_room_id
    ), '[]'::jsonb) else '[]'::jsonb end,
    'playback', case when v_state.room_id is null then null else public.playback_dto(v_state) end
  );
end $$;

-- ---------------------------------------------------------------------------
-- Privileges
-- ---------------------------------------------------------------------------

revoke execute on function
  public.kick_member(uuid, uuid), public.ban_member(uuid, uuid), public.unban_member(uuid, uuid),
  public.mark_chat_seen(uuid, uuid)
  from public, anon;
grant execute on function
  public.kick_member(uuid, uuid), public.ban_member(uuid, uuid), public.unban_member(uuid, uuid),
  public.mark_chat_seen(uuid, uuid)
  to authenticated;

-- ===== 20261022001500_resume_room.sql =====
-- Coming back to a room the client remembers (page reload, reopened tab).
-- The answer tells the three failure cases apart, so the UI can say what happened:
--   ROOM_NOT_FOUND  the room does not exist (any more)
--   ROOM_CLOSED     the owner closed it, or it expired while empty
--   NOT_MEMBER      the room lives, but this user is no longer in it (left, kicked, dropped after 5 offline minutes)
create function public.resume_room(p_room_id uuid) returns jsonb
language plpgsql security definer set search_path = public
as $$
declare
  v_uid uuid := public.require_uid();
  v_room public.rooms;
begin
  select * into v_room from public.rooms where id = p_room_id;
  if v_room.id is null then
    return jsonb_build_object('error', 'ROOM_NOT_FOUND');
  end if;
  if v_room.status <> 'active' then
    return jsonb_build_object('error', 'ROOM_CLOSED');
  end if;
  if exists (select 1 from public.room_bans where room_id = p_room_id and user_id = v_uid) then
    return jsonb_build_object('error', 'BANNED');
  end if;
  if not exists (select 1 from public.room_members where room_id = p_room_id and user_id = v_uid) then
    return jsonb_build_object('error', 'NOT_MEMBER', 'globalId', v_room.global_id, 'visibility', v_room.visibility);
  end if;
  perform public.mark_active(p_room_id, v_uid);
  return public.build_snapshot(p_room_id, v_uid);
end $$;

revoke execute on function public.resume_room(uuid) from public, anon;
grant execute on function public.resume_room(uuid) to authenticated;

-- ===== 20261022001600_heartbeat_retention.sql =====
-- Heartbeat that answers: the client learns within one beat that the room closed or that its seat was lost
-- (cheaper than a full snapshot). Plus housekeeping so tables and indexes stay small.

create function public.heartbeat_room(p_room_id uuid) returns text
language plpgsql security definer set search_path = public
as $$
declare
  v_uid uuid := public.require_uid();
  v_status text;
begin
  select status into v_status from public.rooms where id = p_room_id;
  if v_status is null then
    return 'ROOM_NOT_FOUND';
  end if;
  if v_status <> 'active' then
    return 'ROOM_CLOSED';
  end if;
  if exists (select 1 from public.room_bans where room_id = p_room_id and user_id = v_uid) then
    return 'BANNED';
  end if;
  if not exists (select 1 from public.room_members where room_id = p_room_id and user_id = v_uid) then
    return 'NOT_MEMBER';
  end if;
  perform public.mark_active(p_room_id, v_uid);
  return 'OK';
end $$;
revoke execute on function public.heartbeat_room(uuid) from public, anon;
grant execute on function public.heartbeat_room(uuid) to authenticated;

-- Seat counting and the offline sweep look rows up by activity time
create index if not exists member_activity_room_active_idx on public.member_activity (room_id, last_active_at desc);

-- Closed rooms are kept for a few days (so "this room was closed" can still be answered), then removed with everything attached
create function public.purge_closed_rooms(p_keep interval default interval '3 days') returns integer
language plpgsql security definer set search_path = public
as $$
declare v_count integer;
begin
  with gone as (
    delete from public.rooms where status = 'closed' and updated_at < now() - p_keep returning id
  )
  select count(*) into v_count from gone;
  -- Leftovers of the throttling / idempotency tables
  delete from public.rate_events where at < now() - interval '1 hour';
  delete from public.idempotency_keys where created_at < now() - interval '1 day';
  delete from public.processed_commands where created_at < now() - interval '1 day';
  return v_count;
end $$;
revoke execute on function public.purge_closed_rooms(interval) from public, anon, authenticated;

do $$
begin
  if to_regclass('cron.job') is not null then
    perform cron.schedule('omioroom-purge-closed-rooms', '17 3 * * *', $job$ select public.purge_closed_rooms(interval '3 days') $job$);
  end if;
exception when others then
  raise notice 'could not schedule cron job: %', sqlerrm;
end $$;

-- ===== 20261022001700_chat_seen_realtime.sql =====
-- Read receipts update live: members may read their room's chat_seen rows and receive their changes.
grant select on public.chat_seen to authenticated;
create policy chat_seen_read on public.chat_seen for select to authenticated
  using (public.is_room_member(room_id));

do $$
begin
  if exists (select 1 from pg_publication where pubname = 'supabase_realtime')
     and not exists (
       select 1 from pg_publication_tables
       where pubname = 'supabase_realtime' and schemaname = 'public' and tablename = 'chat_seen'
     ) then
    alter publication supabase_realtime add table public.chat_seen;
  end if;
end $$;

-- ===== 20261022001800_chat_seen_baseline.sql =====
-- Read receipts must reflect real reading. Joining used to record "seen up to now", which showed double
-- ticks for messages nobody read. Joining now only sets a baseline for the unread counter.
alter table public.chat_seen add column baseline_at timestamptz not null default now();
alter table public.chat_seen alter column last_seen_at drop not null;
alter table public.chat_seen alter column last_seen_at drop default;
update public.chat_seen set baseline_at = last_seen_at, last_seen_at = null where last_seen_message_id is null;

create or replace function public.mark_chat_seen(p_room_id uuid, p_message_id uuid) returns void
language plpgsql security definer set search_path = public
as $$
declare
  v_uid uuid := public.require_uid();
  v_at timestamptz;
begin
  perform public.assert_active_member(p_room_id, v_uid);
  perform public.check_rate(v_uid, 'chat_seen', 60, interval '10 seconds');
  select created_at into v_at from public.chat_messages where id = p_message_id and room_id = p_room_id;
  if v_at is null then
    return;
  end if;
  insert into public.chat_seen (room_id, user_id, last_seen_message_id, last_seen_at)
  values (p_room_id, v_uid, p_message_id, v_at)
  on conflict (room_id, user_id) do update
    set last_seen_message_id = excluded.last_seen_message_id, last_seen_at = excluded.last_seen_at
    where public.chat_seen.last_seen_at is null or public.chat_seen.last_seen_at < excluded.last_seen_at;
end $$;

create or replace function public.build_snapshot(p_room_id uuid, p_viewer uuid) returns jsonb
language plpgsql stable security definer set search_path = public
as $$
declare
  v_room public.rooms;
  v_state public.playback_state;
  v_seen timestamptz;
  v_base timestamptz;
begin
  select * into v_room from public.rooms where id = p_room_id;
  select * into v_state from public.playback_state where room_id = p_room_id;
  select last_seen_at, baseline_at into v_seen, v_base from public.chat_seen where room_id = p_room_id and user_id = p_viewer;
  return jsonb_build_object(
    'room', public.room_dto(v_room),
    'isOwner', v_room.owner_id = p_viewer,
    'canControl', public.can_control_playback(p_room_id, p_viewer),
    'participants', coalesce((
      select jsonb_agg(jsonb_build_object(
        'userId', m.user_id,
        'displayName', p.display_name,
        'role', m.role,
        'canControl', m.role = 'owner' or m.can_control,
        'joinedAt', m.joined_at,
        'isOnline', coalesce(a.last_active_at > public.seat_active_cutoff(), false),
        'chatSeenAt', s.last_seen_at
      ) order by m.joined_at)
      from public.room_members m
      join public.profiles p on p.id = m.user_id
      left join public.member_activity a on a.room_id = m.room_id and a.user_id = m.user_id
      left join public.chat_seen s on s.room_id = m.room_id and s.user_id = m.user_id
      where m.room_id = p_room_id
    ), '[]'::jsonb),
    'unreadCount', (
      select count(*) from public.chat_messages c
      where c.room_id = p_room_id and c.sender_id <> p_viewer and c.created_at > greatest(coalesce(v_seen, '-infinity'::timestamptz), coalesce(v_base, '-infinity'::timestamptz))
    ),
    'bannedUsers', case when v_room.owner_id = p_viewer then coalesce((
      select jsonb_agg(jsonb_build_object('userId', b.user_id, 'displayName', p.display_name) order by b.banned_at)
      from public.room_bans b join public.profiles p on p.id = b.user_id
      where b.room_id = p_room_id
    ), '[]'::jsonb) else '[]'::jsonb end,
    'playback', case when v_state.room_id is null then null else public.playback_dto(v_state) end
  );
end $$;


-- ===== 20261022001900_rooms_survive_owner_leaving.sql =====
-- A room the owner left (without closing it) stays as it was: video, position, settings, key, chat.
--  * It is no longer closed after 5 empty minutes; it closes after 7 days without anyone inside.
--  * Playback is paused where the last person left, so coming back does not find the video "ahead".

create function public.pause_empty_rooms() returns integer
language plpgsql security definer set search_path = public
as $$
declare
  v_count integer;
  v_now bigint := public.server_time_ms();
begin
  with empty as (
    select p.room_id
    from public.playback_state p
    join public.rooms r on r.id = p.room_id and r.status = 'active'
    where p.status in ('playing', 'buffering')
      and not exists (
        select 1 from public.member_activity m
        where m.room_id = p.room_id and m.last_active_at > public.seat_active_cutoff()
      )
  ), paused as (
    update public.playback_state p set
      anchor_position = public.expected_position(p, v_now),
      anchor_server_time = v_now,
      status = 'paused',
      buffering = '{}'::jsonb,
      resume_after_buffer = false,
      revision = p.revision + 1
    where p.room_id in (select room_id from empty)
    returning 1
  )
  select count(*) into v_count from paused;
  return v_count;
end $$;
revoke execute on function public.pause_empty_rooms() from public, anon, authenticated;

do $$
begin
  if to_regclass('cron.job') is not null then
    perform cron.unschedule('omioroom-close-inactive-rooms');
    perform cron.schedule(
      'omioroom-close-inactive-rooms',
      '* * * * *',
      $job$ select public.pause_empty_rooms(), public.close_inactive_rooms(interval '7 days') $job$
    );
  end if;
exception when others then
  raise notice 'could not reschedule cron job: %', sqlerrm;
end $$;

-- ===== 20261022002000_offline_drop_10_minutes.sql =====
-- Members who stay offline are dropped from the list after 10 minutes (was 5).
create or replace function public.drop_offline_members(p_max_idle interval default interval '10 minutes') returns integer
language plpgsql security definer set search_path = public
as $$
declare
  v_count integer := 0;
  v_row record;
begin
  for v_row in
    select m.room_id, m.user_id
    from public.room_members m
    join public.rooms r on r.id = m.room_id and r.status = 'active'
    left join public.member_activity a on a.room_id = m.room_id and a.user_id = m.user_id
    where m.role <> 'owner'
      and coalesce(a.last_active_at, m.joined_at) < now() - p_max_idle
  loop
    perform public.remove_member(v_row.room_id, v_row.user_id);
    v_count := v_count + 1;
  end loop;
  return v_count;
end $$;
revoke execute on function public.drop_offline_members(interval) from public, anon, authenticated;

do $$
begin
  if to_regclass('cron.job') is not null then
    perform cron.unschedule('omioroom-drop-offline-members');
    perform cron.schedule(
      'omioroom-drop-offline-members',
      '* * * * *',
      $job$ select public.drop_offline_members(interval '10 minutes') $job$
    );
  end if;
exception when others then
  raise notice 'could not reschedule cron job: %', sqlerrm;
end $$;

-- ===== 20261022002100_room_lifetime_7_days.sql =====
-- A room lives for 7 days from its creation, or until the owner closes it earlier. Leaving does not end it.
create function public.close_expired_rooms(p_ttl interval default interval '7 days') returns integer
language plpgsql security definer set search_path = public
as $$
declare v_count integer;
begin
  with closed as (
    update public.rooms set status = 'closed', revision = revision + 1, updated_at = now()
    where status = 'active' and created_at < now() - p_ttl
    returning id
  ), cleared as (
    delete from public.chat_messages where room_id in (select id from closed)
  )
  select count(*) into v_count from closed;
  return v_count;
end $$;
revoke execute on function public.close_expired_rooms(interval) from public, anon, authenticated;

do $$
begin
  if to_regclass('cron.job') is not null then
    perform cron.unschedule('omioroom-close-inactive-rooms');
    perform cron.schedule(
      'omioroom-close-inactive-rooms',
      '* * * * *',
      $job$ select public.pause_empty_rooms(), public.close_expired_rooms(interval '7 days') $job$
    );
  end if;
exception when others then
  raise notice 'could not reschedule cron job: %', sqlerrm;
end $$;

-- ===== 20261022002200_idle_deadline_7_days.sql =====
-- Room lifetime: a room self-destructs after 7 days with nobody inside. Any visit resets the deadline.
-- While it is empty, the remaining time is exposed as room.expiresAt (null while someone is inside).

-- Leaving must not erase the "last seen" time: free the seat (older than the 90 s activity window) but keep it recent
create or replace function public.leave_room(p_room_id uuid) returns void
language plpgsql security definer set search_path = public
as $$
declare v_uid uuid := public.require_uid();
begin
  if exists (select 1 from public.rooms where id = p_room_id and owner_id = v_uid) then
    update public.member_activity set last_active_at = least(last_active_at, now() - interval '2 minutes')
      where room_id = p_room_id and user_id = v_uid;
  else
    perform public.remove_member(p_room_id, v_uid);
  end if;
end $$;

-- Rooms whose owner left earlier carry the 1970 marker: treat their leaving as just now
update public.member_activity set last_active_at = now() - interval '2 minutes' where last_active_at < '2000-01-01';

create or replace function public.room_dto(p_room public.rooms) returns jsonb
language sql stable security definer set search_path = public
as $$
  select jsonb_build_object(
    'id', p_room.id,
    'globalId', p_room.global_id,
    'ownerUserId', p_room.owner_id,
    'title', p_room.title,
    'visibility', p_room.visibility,
    'status', p_room.status,
    'createdAt', p_room.created_at,
    'updatedAt', p_room.updated_at,
    'participantCount', public.active_seat_count(p_room.id),
    'maxParticipants', p_room.max_participants,
    'controlMode', p_room.control_mode,
    'revision', p_room.revision,
    'expiresAt', case
      when p_room.status = 'active' and public.active_seat_count(p_room.id) = 0 then
        coalesce((select max(a.last_active_at) from public.member_activity a where a.room_id = p_room.id), p_room.created_at)
        + interval '7 days'
    end
  )
$$;

create function public.close_idle_rooms(p_ttl interval default interval '7 days') returns integer
language plpgsql security definer set search_path = public
as $$
declare v_count integer;
begin
  with closed as (
    update public.rooms r set status = 'closed', revision = r.revision + 1, updated_at = now()
    where r.status = 'active'
      and coalesce((select max(a.last_active_at) from public.member_activity a where a.room_id = r.id), r.created_at)
          < now() - p_ttl
    returning r.id
  ), cleared as (
    delete from public.chat_messages where room_id in (select id from closed)
  )
  select count(*) into v_count from closed;
  return v_count;
end $$;
revoke execute on function public.close_idle_rooms(interval) from public, anon, authenticated;

do $$
begin
  if to_regclass('cron.job') is not null then
    perform cron.unschedule('omioroom-close-inactive-rooms');
    perform cron.schedule(
      'omioroom-close-inactive-rooms',
      '* * * * *',
      $job$ select public.pause_empty_rooms(), public.close_idle_rooms(interval '7 days') $job$
    );
  end if;
exception when others then
  raise notice 'could not reschedule cron job: %', sqlerrm;
end $$;

-- ===== 20261022002300_reject_same_media.sql =====
-- Sending a link that points at the video already in the player is refused (MEDIA_ALREADY_LOADED).
create or replace function public.player_command(
  p_room_id uuid,
  p_command_id uuid,
  p_type text,
  p_position double precision default null,
  p_media jsonb default null,
  p_playback_rate double precision default null,
  p_expected_revision integer default null
) returns jsonb
language plpgsql security definer set search_path = public
as $$
declare
  v_uid uuid := public.require_uid();
  v_state public.playback_state;
  v_now bigint;
  v_status text;
  v_pos double precision;
  v_rate double precision;
  v_media jsonb;
begin
  perform public.assert_active_member(p_room_id, v_uid);
  if not public.can_control_playback(p_room_id, v_uid) then
    raise exception 'FORBIDDEN';
  end if;
  -- Generous burst allowance (scrubbing, quick toggles) but protects the database from floods
  perform public.check_rate(v_uid, 'player', 60, interval '10 seconds');

  if p_type not in ('play', 'pause', 'seek', 'change-media', 'set-rate', 'buffering') then
    raise exception 'INVALID_PAYLOAD';
  end if;
  if p_position is not null and p_position < 0 then
    raise exception 'INVALID_PAYLOAD';
  end if;

  -- Row lock gives every room a deterministic command order.
  select * into v_state from public.playback_state where room_id = p_room_id for update;
  if v_state.room_id is null then
    insert into public.playback_state (room_id, anchor_server_time)
      values (p_room_id, public.server_time_ms())
      returning * into v_state;
  end if;

  perform public.mark_active(p_room_id, v_uid);

  -- Duplicate delivery of the same command never applies twice.
  if exists (select 1 from public.processed_commands where room_id = p_room_id and command_id = p_command_id) then
    return public.playback_dto(v_state);
  end if;

  -- A command based on an older revision must not overwrite newer state.
  if p_expected_revision is not null and p_expected_revision < v_state.revision then
    return public.playback_dto(v_state);
  end if;

  v_now := public.server_time_ms();
  v_status := v_state.status;
  v_pos := v_state.anchor_position;
  v_rate := v_state.playback_rate;
  v_media := v_state.media;

  if p_type = 'play' then
    v_status := 'playing';
    v_pos := coalesce(p_position, public.expected_position(v_state, v_now));
  elsif p_type = 'pause' then
    v_status := 'paused';
    v_pos := coalesce(p_position, public.expected_position(v_state, v_now));
  elsif p_type = 'seek' then
    v_pos := coalesce(p_position, 0);
  elsif p_type = 'buffering' then
    v_status := 'buffering';
    v_pos := coalesce(p_position, public.expected_position(v_state, v_now));
  elsif p_type = 'set-rate' then
    if p_playback_rate is null or p_playback_rate < 0.25 or p_playback_rate > 3 then
      raise exception 'INVALID_PAYLOAD';
    end if;
    v_pos := public.expected_position(v_state, v_now);
    v_rate := p_playback_rate;
  elsif p_type = 'change-media' then
    if p_media is null
       or coalesce(p_media ->> 'type', '') not in ('youtube','html5','vk','rutube','vimeo','hls')
       or coalesce(p_media ->> 'sourceId', '') = ''
       or coalesce(p_media ->> 'canonicalUrl', '') !~* '^https?://' then
      raise exception 'MEDIA_UNSUPPORTED';
    end if;
    if v_state.media is not null
       and v_state.media ->> 'type' = p_media ->> 'type'
       and (v_state.media ->> 'sourceId' = p_media ->> 'sourceId'
            or v_state.media ->> 'canonicalUrl' = p_media ->> 'canonicalUrl') then
      raise exception 'MEDIA_ALREADY_LOADED';
    end if;
    v_media := jsonb_build_object(
      'type', p_media ->> 'type',
      'sourceId', p_media ->> 'sourceId',
      'canonicalUrl', p_media ->> 'canonicalUrl'
    );
    v_pos := 0;
    v_status := 'paused';
  end if;

  update public.playback_state set
    buffering = case when p_type in ('play', 'pause', 'change-media') then '{}'::jsonb else buffering end,
    resume_after_buffer = case when p_type in ('play', 'pause', 'change-media') then false else resume_after_buffer end,
    media = v_media,
    status = v_status,
    anchor_position = v_pos,
    anchor_server_time = v_now,
    playback_rate = v_rate,
    revision = revision + 1,
    updated_by = v_uid
  where room_id = p_room_id
  returning * into v_state;

  insert into public.processed_commands (room_id, command_id) values (p_room_id, p_command_id);
  if random() < 0.02 then
    delete from public.processed_commands where created_at < now() - interval '1 day';
  end if;

  return public.playback_dto(v_state);
end $$;

revoke execute on function public.player_command(uuid, uuid, text, double precision, jsonb, double precision, integer) from public, anon;
grant execute on function public.player_command(uuid, uuid, text, double precision, jsonb, double precision, integer) to authenticated;

-- ===== 20261022002400_join_grace.sql =====
-- New arrivals cannot move the room's playback during a short grace period after (re)joining.
-- The server is the single source of truth; a player that is still aligning itself must not rewrite it.

alter table public.member_activity add column session_started_at timestamptz not null default now();

create function public.join_grace() returns interval
language sql immutable
as $$ select interval '3 seconds' $$;

-- A new session starts when someone appears or comes back after being inactive (seat window is 90 s)
create or replace function public.mark_active(p_room uuid, p_user uuid, p_at timestamptz default now()) returns void
language sql security definer set search_path = public
as $$
  insert into public.member_activity (room_id, user_id, last_active_at, session_started_at)
  values (p_room, p_user, p_at, p_at)
  on conflict (room_id, user_id) do update set
    session_started_at = case
      when public.member_activity.last_active_at < p_at - interval '90 seconds' then excluded.session_started_at
      else public.member_activity.session_started_at
    end,
    last_active_at = excluded.last_active_at
$$;

create or replace function public.player_command(
  p_room_id uuid,
  p_command_id uuid,
  p_type text,
  p_position double precision default null,
  p_media jsonb default null,
  p_playback_rate double precision default null,
  p_expected_revision integer default null
) returns jsonb
language plpgsql security definer set search_path = public
as $$
declare
  v_uid uuid := public.require_uid();
  v_state public.playback_state;
  v_now bigint;
  v_status text;
  v_pos double precision;
  v_rate double precision;
  v_media jsonb;
begin
  perform public.assert_active_member(p_room_id, v_uid);
  if not public.can_control_playback(p_room_id, v_uid) then
    raise exception 'FORBIDDEN';
  end if;
  -- Generous burst allowance (scrubbing, quick toggles) but protects the database from floods
  perform public.check_rate(v_uid, 'player', 60, interval '10 seconds');

  if p_type not in ('play', 'pause', 'seek', 'change-media', 'set-rate', 'buffering') then
    raise exception 'INVALID_PAYLOAD';
  end if;
  if p_position is not null and p_position < 0 then
    raise exception 'INVALID_PAYLOAD';
  end if;

  -- Row lock gives every room a deterministic command order.
  select * into v_state from public.playback_state where room_id = p_room_id for update;
  if v_state.room_id is null then
    insert into public.playback_state (room_id, anchor_server_time)
      values (p_room_id, public.server_time_ms())
      returning * into v_state;
  end if;

  perform public.mark_active(p_room_id, v_uid);

  -- A participant who has just arrived (join, reload, back from sleep) is still lining their player up with
  -- the room. Whatever their player reports in that first moment must not move everyone else.
  if p_type in ('play', 'pause', 'seek')
     and v_uid <> (select owner_id from public.rooms where id = p_room_id)
     and exists (
    select 1 from public.member_activity
    where room_id = p_room_id and user_id = v_uid
      and session_started_at > now() - public.join_grace()
  ) then
    return public.playback_dto(v_state);
  end if;

  -- Duplicate delivery of the same command never applies twice.
  if exists (select 1 from public.processed_commands where room_id = p_room_id and command_id = p_command_id) then
    return public.playback_dto(v_state);
  end if;

  -- A command based on an older revision must not overwrite newer state.
  if p_expected_revision is not null and p_expected_revision < v_state.revision then
    return public.playback_dto(v_state);
  end if;

  v_now := public.server_time_ms();
  v_status := v_state.status;
  v_pos := v_state.anchor_position;
  v_rate := v_state.playback_rate;
  v_media := v_state.media;

  if p_type = 'play' then
    v_status := 'playing';
    v_pos := coalesce(p_position, public.expected_position(v_state, v_now));
  elsif p_type = 'pause' then
    v_status := 'paused';
    v_pos := coalesce(p_position, public.expected_position(v_state, v_now));
  elsif p_type = 'seek' then
    v_pos := coalesce(p_position, 0);
  elsif p_type = 'buffering' then
    v_status := 'buffering';
    v_pos := coalesce(p_position, public.expected_position(v_state, v_now));
  elsif p_type = 'set-rate' then
    if p_playback_rate is null or p_playback_rate < 0.25 or p_playback_rate > 3 then
      raise exception 'INVALID_PAYLOAD';
    end if;
    v_pos := public.expected_position(v_state, v_now);
    v_rate := p_playback_rate;
  elsif p_type = 'change-media' then
    if p_media is null
       or coalesce(p_media ->> 'type', '') not in ('youtube','html5','vk','rutube','vimeo','hls')
       or coalesce(p_media ->> 'sourceId', '') = ''
       or coalesce(p_media ->> 'canonicalUrl', '') !~* '^https?://' then
      raise exception 'MEDIA_UNSUPPORTED';
    end if;
    if v_state.media is not null
       and v_state.media ->> 'type' = p_media ->> 'type'
       and (v_state.media ->> 'sourceId' = p_media ->> 'sourceId'
            or v_state.media ->> 'canonicalUrl' = p_media ->> 'canonicalUrl') then
      raise exception 'MEDIA_ALREADY_LOADED';
    end if;
    v_media := jsonb_build_object(
      'type', p_media ->> 'type',
      'sourceId', p_media ->> 'sourceId',
      'canonicalUrl', p_media ->> 'canonicalUrl'
    );
    v_pos := 0;
    v_status := 'paused';
  end if;

  update public.playback_state set
    buffering = case when p_type in ('play', 'pause', 'change-media') then '{}'::jsonb else buffering end,
    resume_after_buffer = case when p_type in ('play', 'pause', 'change-media') then false else resume_after_buffer end,
    media = v_media,
    status = v_status,
    anchor_position = v_pos,
    anchor_server_time = v_now,
    playback_rate = v_rate,
    revision = revision + 1,
    updated_by = v_uid
  where room_id = p_room_id
  returning * into v_state;

  insert into public.processed_commands (room_id, command_id) values (p_room_id, p_command_id);
  if random() < 0.02 then
    delete from public.processed_commands where created_at < now() - interval '1 day';
  end if;

  return public.playback_dto(v_state);
end $$;

revoke execute on function public.player_command(uuid, uuid, text, double precision, jsonb, double precision, integer) from public, anon;
grant execute on function public.player_command(uuid, uuid, text, double precision, jsonb, double precision, integer) to authenticated;

-- ===== 20261022002500_room_mutes.sql =====
-- Muting: the owner and people who may control playback can mute ordinary participants.
-- A muted participant cannot send chat messages (enforced here) and their microphone is silenced
-- (clients obey the list from the room snapshot). The owner and people who may control cannot be muted.

create table public.room_mutes (
  room_id uuid not null references public.rooms (id) on delete cascade,
  user_id uuid not null references public.profiles (id) on delete cascade,
  muted_by uuid references public.profiles (id) on delete set null,
  muted_at timestamptz not null default now(),
  primary key (room_id, user_id)
);
alter table public.room_mutes enable row level security;
revoke all on public.room_mutes from anon, authenticated;
grant select on public.room_mutes to authenticated;
create policy room_mutes_read on public.room_mutes for select to authenticated
  using (public.is_room_member(room_id));

do $$
begin
  if exists (select 1 from pg_publication where pubname = 'supabase_realtime')
     and not exists (
       select 1 from pg_publication_tables
       where pubname = 'supabase_realtime' and schemaname = 'public' and tablename = 'room_mutes'
     ) then
    alter publication supabase_realtime add table public.room_mutes;
  end if;
end $$;

create function public.set_member_muted(p_room_id uuid, p_user_id uuid, p_muted boolean) returns void
language plpgsql security definer set search_path = public
as $$
declare v_uid uuid := public.require_uid();
begin
  perform public.assert_active_member(p_room_id, v_uid);
  if not public.can_control_playback(p_room_id, v_uid) then
    raise exception 'FORBIDDEN';
  end if;
  if p_user_id is null or p_user_id = v_uid
     or not exists (select 1 from public.room_members where room_id = p_room_id and user_id = p_user_id) then
    raise exception 'INVALID_PAYLOAD';
  end if;
  if coalesce(p_muted, false) then
    -- The owner and anyone who may control the room cannot be muted
    if public.can_control_playback(p_room_id, p_user_id) then
      raise exception 'FORBIDDEN';
    end if;
    insert into public.room_mutes (room_id, user_id, muted_by) values (p_room_id, p_user_id, v_uid)
      on conflict (room_id, user_id) do nothing;
  else
    delete from public.room_mutes where room_id = p_room_id and user_id = p_user_id;
  end if;
end $$;
revoke execute on function public.set_member_muted(uuid, uuid, boolean) from public, anon;
grant execute on function public.set_member_muted(uuid, uuid, boolean) to authenticated;

-- Muted participants cannot post to the chat, whichever function inserts the message
create function public.block_muted_chat() returns trigger
language plpgsql security definer set search_path = public
as $$
begin
  if exists (select 1 from public.room_mutes where room_id = new.room_id and user_id = new.sender_id) then
    raise exception 'MUTED';
  end if;
  return new;
end $$;
create trigger chat_messages_block_muted before insert on public.chat_messages
  for each row execute function public.block_muted_chat();

create or replace function public.build_snapshot(p_room_id uuid, p_viewer uuid) returns jsonb
language plpgsql stable security definer set search_path = public
as $$
declare
  v_room public.rooms;
  v_state public.playback_state;
  v_seen timestamptz;
  v_base timestamptz;
begin
  select * into v_room from public.rooms where id = p_room_id;
  select * into v_state from public.playback_state where room_id = p_room_id;
  select last_seen_at, baseline_at into v_seen, v_base from public.chat_seen where room_id = p_room_id and user_id = p_viewer;
  return jsonb_build_object(
    'room', public.room_dto(v_room),
    'isOwner', v_room.owner_id = p_viewer,
    'canControl', public.can_control_playback(p_room_id, p_viewer),
    'participants', coalesce((
      select jsonb_agg(jsonb_build_object(
        'userId', m.user_id,
        'displayName', p.display_name,
        'role', m.role,
        'canControl', m.role = 'owner' or m.can_control,
        'joinedAt', m.joined_at,
        'isOnline', coalesce(a.last_active_at > public.seat_active_cutoff(), false),
        'chatSeenAt', s.last_seen_at
      ) order by m.joined_at)
      from public.room_members m
      join public.profiles p on p.id = m.user_id
      left join public.member_activity a on a.room_id = m.room_id and a.user_id = m.user_id
      left join public.chat_seen s on s.room_id = m.room_id and s.user_id = m.user_id
      where m.room_id = p_room_id
    ), '[]'::jsonb),
    'mutedUserIds', coalesce((select jsonb_agg(mu.user_id) from public.room_mutes mu where mu.room_id = p_room_id), '[]'::jsonb),
    'unreadCount', (
      select count(*) from public.chat_messages c
      where c.room_id = p_room_id and c.sender_id <> p_viewer and c.created_at > greatest(coalesce(v_seen, '-infinity'::timestamptz), coalesce(v_base, '-infinity'::timestamptz))
    ),
    'bannedUsers', case when v_room.owner_id = p_viewer then coalesce((
      select jsonb_agg(jsonb_build_object('userId', b.user_id, 'displayName', p.display_name) order by b.banned_at)
      from public.room_bans b join public.profiles p on p.id = b.user_id
      where b.room_id = p_room_id
    ), '[]'::jsonb) else '[]'::jsonb end,
    'playback', case when v_state.room_id is null then null else public.playback_dto(v_state) end
  );
end $$;


-- ===== 20261022002600_per_user_room_limit.sql =====
-- Active rooms per owner: 1 by default, a different number for chosen accounts (table user_room_limits).
create table public.user_room_limits (
  user_id uuid primary key references public.profiles (id) on delete cascade,
  max_rooms integer not null check (max_rooms between 1 and 50)
);
alter table public.user_room_limits enable row level security;
revoke all on public.user_room_limits from anon, authenticated;

create function public.room_limit_for(p_user uuid) returns integer
language sql stable security definer set search_path = public
as $$ select coalesce((select max_rooms from public.user_room_limits where user_id = p_user), 1) $$;
revoke execute on function public.room_limit_for(uuid) from public, anon, authenticated;

create or replace function public.room_limit_per_user() returns integer
language sql stable security definer set search_path = public
as $$ select public.room_limit_for(auth.uid()) $$;

-- ===== 20261022002700_input_validation.sql =====
-- Input hygiene. All database access already goes through parameterised functions and Row Level Security
-- (no query is ever built from user text), so injection is not possible; this adds a second line of defence:
-- hidden control characters, direction overrides and punctuation that has no business in names are refused.

-- No control characters, zero-width characters or bidirectional overrides (they hide text and spoof names)
create function public.is_clean_text(p text) returns boolean
language sql immutable set search_path = public
as $$
  select p is null or p !~ '[\x01-\x08\x0b\x0c\x0e-\x1f\x7f​-‏‪-‮⁠-⁤﻿]'
$$;

-- Names: letters, digits, spaces, dot, hyphen and underscore only
create function public.is_safe_name(p text) returns boolean
language sql immutable set search_path = public
as $$
  select p is not null
     and public.is_clean_text(p)
     and p !~ '[!-,/:-@[-^`{-~]'
$$;

-- Names given by the user (nickname change)
create or replace function public.update_display_name(p_name text) returns jsonb
language plpgsql security definer set search_path = public
as $$
declare
  v_uid uuid := public.require_uid();
  v_name text := trim(coalesce(p_name, ''));
  v_profile public.profiles;
begin
  select * into v_profile from public.profiles where id = v_uid;
  if v_profile.kind = 'registered' then
    raise exception 'FORBIDDEN';
  end if;
  if char_length(v_name) < 2 or char_length(v_name) > 30 or not public.is_safe_name(v_name) then
    raise exception 'INVALID_PAYLOAD';
  end if;
  update public.profiles
    set display_name = v_name, kind = 'nickname', updated_at = now()
    where id = v_uid
    returning * into v_profile;
  return jsonb_build_object(
    'id', v_profile.id, 'kind', v_profile.kind, 'displayName', v_profile.display_name
  );
end $$;

-- Registration: a username that is sent explicitly must be clean (a crafted one is refused);
-- a name derived from the e-mail address is cleaned instead, so odd addresses still work
create or replace function public.handle_auth_user() returns trigger
language plpgsql security definer set search_path = public
as $$
declare
  v_given text;
  v_username text;
begin
  if tg_op = 'INSERT' and coalesce(new.is_anonymous, false) then
    insert into public.profiles (id, kind, display_name)
    values (new.id, 'anonymous', public.random_display_name());
    return new;
  end if;

  if tg_op = 'INSERT' or (coalesce(old.is_anonymous, false) and not coalesce(new.is_anonymous, false)) then
    v_given := nullif(trim(new.raw_user_meta_data ->> 'username'), '');
    if v_given is not null then
      if char_length(v_given) < 2 or char_length(v_given) > 30 or not public.is_safe_name(v_given) then
        raise exception 'INVALID_PAYLOAD';
      end if;
      v_username := v_given;
    else
      v_username := left(regexp_replace(split_part(new.email, '@', 1), '[^[:alnum:]._-]', '_', 'g'), 30);
      if char_length(v_username) < 2 then v_username := v_username || '_u'; end if;
    end if;

    if tg_op = 'INSERT' then
      insert into public.profiles (id, kind, display_name, username)
      values (new.id, 'registered', v_username, v_username);
    else
      update public.profiles
        set kind = 'registered', username = v_username, display_name = v_username, updated_at = now()
        where id = new.id;
    end if;
  end if;
  return new;
end $$;

-- Chat text and names in the chat
create function public.validate_chat_message() returns trigger
language plpgsql set search_path = public
as $$
begin
  if not public.is_clean_text(new.body) or not public.is_clean_text(new.sender_name) then
    raise exception 'INVALID_PAYLOAD';
  end if;
  return new;
end $$;
create trigger chat_messages_validate before insert on public.chat_messages
  for each row execute function public.validate_chat_message();

-- Video links: bounded length, no whitespace or hidden characters
create function public.validate_playback_media() returns trigger
language plpgsql set search_path = public
as $$
begin
  if new.media is not null and (
       char_length(coalesce(new.media ->> 'canonicalUrl', '')) > 2048
       or char_length(coalesce(new.media ->> 'sourceId', '')) > 512
       or coalesce(new.media ->> 'canonicalUrl', '') ~ '\s'
       or not public.is_clean_text(new.media ->> 'canonicalUrl')
       or not public.is_clean_text(new.media ->> 'sourceId')
     ) then
    raise exception 'MEDIA_UNSUPPORTED';
  end if;
  return new;
end $$;
create trigger playback_state_validate_media before insert or update of media on public.playback_state
  for each row execute function public.validate_playback_media();

-- ===== 20261022002800_chat_image_cleanup.sql =====
-- Chat images of closed or deleted rooms are removed by the Edge Function cleanup-chat-images (storage files
-- cannot be deleted with SQL). It runs every hour. The shared secret lives in the Vault under the name
-- 'cleanup_secret' (set once: select vault.create_secret('<secret>', 'cleanup_secret');) and as the function
-- secret CLEANUP_SECRET (supabase secrets set CLEANUP_SECRET=<secret>).
do $$
begin
  if exists (select 1 from pg_available_extensions where name = 'pg_net') then
    create extension if not exists pg_net;
  end if;
exception when others then
  raise notice 'could not enable pg_net: %', sqlerrm;
end $$;

do $$
begin
  if to_regclass('cron.job') is not null and to_regnamespace('net') is not null then
    perform cron.schedule(
      'omioroom-cleanup-chat-images',
      '7 * * * *',
      $job$
        select net.http_post(
          url := 'https://dmpmwcxohniwfczkoxkk.supabase.co/functions/v1/cleanup-chat-images',
          headers := jsonb_build_object(
            'content-type', 'application/json',
            'x-cleanup-secret', coalesce((select decrypted_secret from vault.decrypted_secrets where name = 'cleanup_secret'), '')
          ),
          body := '{}'::jsonb
        )
      $job$
    );
  end if;
exception when others then
  raise notice 'could not schedule cron job: %', sqlerrm;
end $$;

-- ===== 20261022002900_owner_blacklist.sql =====
-- The blacklist belongs to the owner and works in all of their rooms: someone banned in one room cannot enter
-- the others, and the owner manages the list (and lifts bans) from their settings.

create table public.owner_bans (
  owner_id uuid not null references public.profiles (id) on delete cascade,
  user_id uuid not null references public.profiles (id) on delete cascade,
  banned_at timestamptz not null default now(),
  primary key (owner_id, user_id)
);
alter table public.owner_bans enable row level security;
revoke all on public.owner_bans from anon, authenticated;

-- Existing room bans become bans for the whole owner
insert into public.owner_bans (owner_id, user_id, banned_at)
  select r.owner_id, b.user_id, b.banned_at from public.room_bans b join public.rooms r on r.id = b.room_id
  on conflict do nothing;

create function public.is_banned(p_room uuid, p_user uuid) returns boolean
language sql stable security definer set search_path = public
as $$
  select exists (select 1 from public.room_bans where room_id = p_room and user_id = p_user)
      or exists (
        select 1 from public.owner_bans ob join public.rooms r on r.owner_id = ob.owner_id
        where r.id = p_room and ob.user_id = p_user
      )
$$;
revoke execute on function public.is_banned(uuid, uuid) from public, anon, authenticated;

-- Banning removes the person from every room of this owner
create or replace function public.ban_member(p_room_id uuid, p_user_id uuid) returns void
language plpgsql security definer set search_path = public
as $$
declare
  v_uid uuid := public.require_uid();
  v_room public.rooms := public.owned_active_room(p_room_id, v_uid);
  v_other record;
begin
  if p_user_id is null or p_user_id = v_uid or p_user_id = v_room.owner_id then
    raise exception 'INVALID_PAYLOAD';
  end if;
  insert into public.owner_bans (owner_id, user_id) values (v_uid, p_user_id) on conflict do nothing;
  for v_other in select id from public.rooms where owner_id = v_uid and status = 'active' loop
    perform public.remove_member(v_other.id, p_user_id);
  end loop;
end $$;

-- Lifting a ban restores access to all the owner's rooms
create or replace function public.unban_member(p_room_id uuid, p_user_id uuid) returns void
language plpgsql security definer set search_path = public
as $$
declare
  v_uid uuid := public.require_uid();
  v_room public.rooms := public.owned_active_room(p_room_id, v_uid);
begin
  delete from public.owner_bans where owner_id = v_uid and user_id = p_user_id;
  delete from public.room_bans where user_id = p_user_id
    and room_id in (select id from public.rooms where owner_id = v_uid);
end $$;

-- The owner's whole list, for the settings screen (works without being inside a room)
create function public.list_banned_users() returns jsonb
language sql stable security definer set search_path = public
as $$
  select coalesce(jsonb_agg(jsonb_build_object('userId', b.user_id, 'displayName', p.display_name) order by b.banned_at), '[]'::jsonb)
  from public.owner_bans b join public.profiles p on p.id = b.user_id
  where b.owner_id = auth.uid()
$$;

create function public.unban_user(p_user_id uuid) returns void
language plpgsql security definer set search_path = public
as $$
declare v_uid uuid := public.require_uid();
begin
  delete from public.owner_bans where owner_id = v_uid and user_id = p_user_id;
  delete from public.room_bans where user_id = p_user_id
    and room_id in (select id from public.rooms where owner_id = v_uid);
end $$;

revoke execute on function public.list_banned_users(), public.unban_user(uuid) from public, anon;
grant execute on function public.list_banned_users(), public.unban_user(uuid) to authenticated;

create or replace function public.join_room(p_global_id text, p_private_code text default null) returns jsonb
language plpgsql security definer set search_path = public
as $$
declare
  v_uid uuid := public.require_uid();
  v_room public.rooms;
  v_member public.room_members;
  v_secret public.room_secrets;
  v_active integer;
begin
  perform public.check_rate(v_uid, 'join_room', 15, interval '60 seconds');

  if p_global_id is null or p_global_id !~ '^[0-9]{6}$' then
    return jsonb_build_object('error', 'INVALID_PAYLOAD');
  end if;

  select * into v_room from public.rooms where global_id = p_global_id and status = 'active';
  if v_room.id is null then
    return jsonb_build_object('error', 'ROOM_NOT_FOUND');
  end if;

  if public.is_banned(v_room.id, v_uid) then
    return jsonb_build_object('error', 'BANNED');
  end if;

  select * into v_member from public.room_members where room_id = v_room.id and user_id = v_uid;

  if v_room.visibility = 'private' and v_room.owner_id <> v_uid and v_member.user_id is null then
    if p_private_code is null or trim(p_private_code) = '' then
      return jsonb_build_object('error', 'PRIVATE_CODE_REQUIRED');
    end if;
    select * into v_secret from public.room_secrets where room_id = v_room.id;
    if v_secret.room_id is null
       or v_secret.revoked_at is not null
       or v_secret.secret_hash <> public.hash_secret(trim(p_private_code)) then
      return jsonb_build_object('error', 'INVALID_PRIVATE_CODE');
    end if;
  end if;

  select count(*) into v_active
    from public.member_activity
    where room_id = v_room.id and user_id <> v_uid and last_active_at > public.seat_active_cutoff();
  if v_active >= v_room.max_participants then
    return jsonb_build_object('error', 'ROOM_FULL');
  end if;

  if v_member.user_id is null then
    insert into public.room_members (room_id, user_id, role) values (v_room.id, v_uid, 'member');
    insert into public.chat_seen (room_id, user_id) values (v_room.id, v_uid) on conflict do nothing;
  end if;
  perform public.mark_active(v_room.id, v_uid);

  return public.build_snapshot(v_room.id, v_uid);
end $$;

create or replace function public.resume_room(p_room_id uuid) returns jsonb
language plpgsql security definer set search_path = public
as $$
declare
  v_uid uuid := public.require_uid();
  v_room public.rooms;
begin
  select * into v_room from public.rooms where id = p_room_id;
  if v_room.id is null then
    return jsonb_build_object('error', 'ROOM_NOT_FOUND');
  end if;
  if v_room.status <> 'active' then
    return jsonb_build_object('error', 'ROOM_CLOSED');
  end if;
  if public.is_banned(p_room_id, v_uid) then
    return jsonb_build_object('error', 'BANNED');
  end if;
  if not exists (select 1 from public.room_members where room_id = p_room_id and user_id = v_uid) then
    return jsonb_build_object('error', 'NOT_MEMBER', 'globalId', v_room.global_id, 'visibility', v_room.visibility);
  end if;
  perform public.mark_active(p_room_id, v_uid);
  return public.build_snapshot(p_room_id, v_uid);
end $$;

create or replace function public.heartbeat_room(p_room_id uuid) returns text
language plpgsql security definer set search_path = public
as $$
declare
  v_uid uuid := public.require_uid();
  v_status text;
begin
  select status into v_status from public.rooms where id = p_room_id;
  if v_status is null then
    return 'ROOM_NOT_FOUND';
  end if;
  if v_status <> 'active' then
    return 'ROOM_CLOSED';
  end if;
  if public.is_banned(p_room_id, v_uid) then
    return 'BANNED';
  end if;
  if not exists (select 1 from public.room_members where room_id = p_room_id and user_id = v_uid) then
    return 'NOT_MEMBER';
  end if;
  perform public.mark_active(p_room_id, v_uid);
  return 'OK';
end $$;

create or replace function public.build_snapshot(p_room_id uuid, p_viewer uuid) returns jsonb
language plpgsql stable security definer set search_path = public
as $$
declare
  v_room public.rooms;
  v_state public.playback_state;
  v_seen timestamptz;
  v_base timestamptz;
begin
  select * into v_room from public.rooms where id = p_room_id;
  select * into v_state from public.playback_state where room_id = p_room_id;
  select last_seen_at, baseline_at into v_seen, v_base from public.chat_seen where room_id = p_room_id and user_id = p_viewer;
  return jsonb_build_object(
    'room', public.room_dto(v_room),
    'isOwner', v_room.owner_id = p_viewer,
    'canControl', public.can_control_playback(p_room_id, p_viewer),
    'participants', coalesce((
      select jsonb_agg(jsonb_build_object(
        'userId', m.user_id,
        'displayName', p.display_name,
        'role', m.role,
        'canControl', m.role = 'owner' or m.can_control,
        'joinedAt', m.joined_at,
        'isOnline', coalesce(a.last_active_at > public.seat_active_cutoff(), false),
        'chatSeenAt', s.last_seen_at
      ) order by m.joined_at)
      from public.room_members m
      join public.profiles p on p.id = m.user_id
      left join public.member_activity a on a.room_id = m.room_id and a.user_id = m.user_id
      left join public.chat_seen s on s.room_id = m.room_id and s.user_id = m.user_id
      where m.room_id = p_room_id
    ), '[]'::jsonb),
    'mutedUserIds', coalesce((select jsonb_agg(mu.user_id) from public.room_mutes mu where mu.room_id = p_room_id), '[]'::jsonb),
    'unreadCount', (
      select count(*) from public.chat_messages c
      where c.room_id = p_room_id and c.sender_id <> p_viewer and c.created_at > greatest(coalesce(v_seen, '-infinity'::timestamptz), coalesce(v_base, '-infinity'::timestamptz))
    ),
    'bannedUsers', case when v_room.owner_id = p_viewer then coalesce((
      select jsonb_agg(jsonb_build_object('userId', b.user_id, 'displayName', p.display_name) order by b.banned_at)
      from public.owner_bans b join public.profiles p on p.id = b.user_id
      where b.owner_id = v_room.owner_id
    ), '[]'::jsonb) else '[]'::jsonb end,
    'playback', case when v_state.room_id is null then null else public.playback_dto(v_state) end
  );
end $$;

-- ===== 20261022003000_media_source_rules.sql =====
-- Which video links a room accepts.
--  * Every room: the link must have the exact shape our own parser produces for its platform, on that platform's
--    own domain. (Players build their iframes from the link, so an arbitrary address would put any page in front
--    of every participant.)
--  * Open rooms: only the four platforms (YouTube, VK Video, RuTube, Vimeo), which age-gate and moderate their
--    own videos. Direct files and HLS streams from any site are for private rooms.

create function public.open_rooms_platforms_only() returns boolean
language sql immutable
as $$ select true $$;

create or replace function public.validate_playback_media() returns trigger
language plpgsql security definer set search_path = public
as $$
declare
  v_url text := coalesce(new.media ->> 'canonicalUrl', '');
  v_id text := coalesce(new.media ->> 'sourceId', '');
  v_type text := new.media ->> 'type';
  v_visibility text;
  v_ok boolean;
begin
  if new.media is null then
    return new;
  end if;

  if char_length(v_url) > 2048 or char_length(v_id) > 512 or v_url ~ '\s'
     or not public.is_clean_text(v_url) or not public.is_clean_text(v_id) then
    raise exception 'MEDIA_UNSUPPORTED';
  end if;

  v_ok := case v_type
    when 'youtube' then v_url ~ '^https://www\.youtube\.com/watch\?v=[A-Za-z0-9_-]{11}$'
                        and v_id = substring(v_url from 'v=([A-Za-z0-9_-]{11})$')
    when 'vk' then v_url ~ '^https://(vk\.com|vkvideo\.ru)/video_ext\.php\?oid=-?[0-9]+&id=[0-9]+(&hash=[A-Za-z0-9]+)?&autoplay=0$'
    when 'rutube' then v_url ~ '^https://rutube\.ru/play/embed/[a-f0-9]{32}(\?p=[A-Za-z0-9%_.~-]+)?$'
    when 'vimeo' then v_url ~ '^https://player\.vimeo\.com/video/[0-9]+(\?h=[a-f0-9]+)?$'
    when 'html5' then v_url ~* '^https?://[^/]+/'
    when 'hls' then v_url ~* '^https?://[^/]+/'
    else false
  end;
  if not coalesce(v_ok, false) then
    raise exception 'MEDIA_UNSUPPORTED';
  end if;

  if v_type in ('html5', 'hls') and public.open_rooms_platforms_only() then
    select visibility into v_visibility from public.rooms where id = new.room_id;
    if v_visibility = 'public' then
      raise exception 'MEDIA_NOT_ALLOWED_IN_OPEN_ROOM';
    end if;
  end if;
  return new;
end $$;

-- Making a room open while it plays a direct file or stream stops that video
create function public.clear_direct_media_on_open() returns trigger
language plpgsql security definer set search_path = public
as $$
begin
  if new.visibility = 'public' and old.visibility is distinct from 'public' and public.open_rooms_platforms_only() then
    update public.playback_state
      set media = null, status = 'paused', anchor_position = 0,
          anchor_server_time = public.server_time_ms(), revision = revision + 1,
          buffering = '{}'::jsonb, resume_after_buffer = false
      where room_id = new.id and media ->> 'type' in ('html5', 'hls');
  end if;
  return new;
end $$;
create trigger rooms_clear_direct_media_on_open after update of visibility on public.rooms
  for each row execute function public.clear_direct_media_on_open();

-- ===== 20261022003100_media_moderation.sql =====
-- Automatic moderation of videos in open rooms.
-- When a video is set in an open room, an Edge Function (moderate-media) looks up its title and age flags at
-- the platform and checks the title against a list of blocked terms. A video that fails is removed from the room,
-- the room is told why (playback.mediaBlocked) and the person who set it gets a strike; three strikes in 24 hours
-- stop that person from changing videos in open rooms for the rest of the day. Private rooms are not moderated.

alter table public.playback_state add column media_blocked text;

create or replace function public.playback_dto(p_state public.playback_state) returns jsonb
language sql stable set search_path = public
as $$
  select jsonb_build_object(
    'roomId', p_state.room_id,
    'media', p_state.media,
    'status', p_state.status,
    'anchorPosition', p_state.anchor_position,
    'anchorServerTime', p_state.anchor_server_time,
    'playbackRate', p_state.playback_rate,
    'revision', p_state.revision,
    'updatedByUserId', p_state.updated_by,
    'bufferingBy', coalesce((select jsonb_agg(k) from jsonb_object_keys(p_state.buffering) as k), '[]'::jsonb),
    'mediaBlocked', p_state.media_blocked
  )
$$;

-- A new video clears the previous "blocked" note
create function public.clear_media_blocked() returns trigger
language plpgsql set search_path = public
as $$
begin
  if new.media is not null and new.media is distinct from old.media then
    new.media_blocked := null;
  end if;
  return new;
end $$;
create trigger playback_state_clear_blocked before update of media on public.playback_state
  for each row execute function public.clear_media_blocked();

-- ---------------------------------------------------------------------------
-- Blocked terms
-- ---------------------------------------------------------------------------

create table public.blocked_terms (
  term text primary key,
  -- 'word': the term must stand as a whole word; 'substring': found anywhere in the title
  mode text not null default 'word' check (mode in ('word', 'substring')),
  kind text not null default 'adult'
);
alter table public.blocked_terms enable row level security;
revoke all on public.blocked_terms from anon, authenticated;

insert into public.blocked_terms (term, mode, kind) values
  ('porn', 'substring', 'adult'), ('porno', 'substring', 'adult'), ('pornhub', 'substring', 'adult'),
  ('xxx', 'word', 'adult'), ('nsfw', 'word', 'adult'), ('hentai', 'substring', 'adult'),
  ('erotic', 'substring', 'adult'), ('erotica', 'substring', 'adult'), ('onlyfans', 'substring', 'adult'),
  ('nude', 'word', 'adult'), ('nudes', 'word', 'adult'), ('naked', 'word', 'adult'), ('sex', 'word', 'adult'),
  ('sexy', 'word', 'adult'), ('blowjob', 'substring', 'adult'), ('handjob', 'substring', 'adult'),
  ('orgasm', 'substring', 'adult'), ('milf', 'word', 'adult'), ('fetish', 'substring', 'adult'),
  ('bdsm', 'word', 'adult'), ('camgirl', 'substring', 'adult'), ('striptease', 'substring', 'adult'),
  ('18+', 'word', 'adult'), ('21+', 'word', 'adult'), ('adults only', 'substring', 'adult'),
  ('gore', 'word', 'violence'), ('snuff', 'word', 'violence'), ('beheading', 'substring', 'violence'),
  ('порно', 'substring', 'adult'), ('порнух', 'substring', 'adult'), ('секс', 'word', 'adult'),
  ('эротик', 'substring', 'adult'), ('эротич', 'substring', 'adult'), ('хентай', 'substring', 'adult'),
  ('голые', 'word', 'adult'), ('голая', 'word', 'adult'), ('голый', 'word', 'adult'),
  ('обнажен', 'substring', 'adult'), ('интим', 'word', 'adult'), ('минет', 'word', 'adult'),
  ('камшот', 'substring', 'adult'), ('вебкам', 'substring', 'adult'), ('стриптиз', 'substring', 'adult'),
  ('для взрослых', 'substring', 'adult'), ('только для взрослых', 'substring', 'adult'),
  ('расчленен', 'substring', 'violence'), ('обезглавл', 'substring', 'violence'), ('зоофил', 'substring', 'adult');

create function public.normalize_title(p text) returns text
language sql immutable set search_path = public
as $$
  select regexp_replace(lower(replace(replace(coalesce(p, ''), 'Ё', 'е'), 'ё', 'е')), '[_./\\|\-]+', ' ', 'g')
$$;

-- The first blocked term found in a text, or null
create function public.find_blocked_term(p_text text) returns text
language sql stable security definer set search_path = public
as $$
  select t.term
  from public.blocked_terms t
  where case t.mode
          when 'substring' then public.normalize_title(p_text) like '%' || t.term || '%'
          else public.normalize_title(p_text) ~ ('(^|[^[:alnum:]])' || regexp_replace(t.term, '([.+*?()\[\]{}|\\^$-])', '\\\1', 'g') || '($|[^[:alnum:]])')
        end
  limit 1
$$;
revoke execute on function public.find_blocked_term(text) from public, anon, authenticated;

-- ---------------------------------------------------------------------------
-- Verdicts, strikes and removal
-- ---------------------------------------------------------------------------

create table public.media_verdicts (
  media_key text primary key,        -- '<type>:<sourceId>'
  title text,
  verdict text not null check (verdict in ('ok', 'blocked', 'unknown')),
  reason text,
  checked_at timestamptz not null default now()
);
alter table public.media_verdicts enable row level security;
revoke all on public.media_verdicts from anon, authenticated;

create table public.moderation_events (
  id bigserial primary key,
  room_id uuid references public.rooms (id) on delete cascade,
  user_id uuid references public.profiles (id) on delete set null,
  kind text not null,
  detail text,
  created_at timestamptz not null default now()
);
create index moderation_events_user_idx on public.moderation_events (user_id, kind, created_at desc);
alter table public.moderation_events enable row level security;
revoke all on public.moderation_events from anon, authenticated;

create function public.media_key_of(p_media jsonb) returns text
language sql immutable
as $$ select (p_media ->> 'type') || ':' || (p_media ->> 'sourceId') $$;

-- Removes the video from the room if it is still the one that was judged
create function public.reject_media(p_room_id uuid, p_media_key text, p_reason text) returns boolean
language plpgsql security definer set search_path = public
as $$
declare
  v_state public.playback_state;
begin
  select * into v_state from public.playback_state where room_id = p_room_id for update;
  if v_state.room_id is null or v_state.media is null or public.media_key_of(v_state.media) <> p_media_key then
    return false;
  end if;
  update public.playback_state set
    media = null, status = 'paused', anchor_position = 0, anchor_server_time = public.server_time_ms(),
    buffering = '{}'::jsonb, resume_after_buffer = false, media_blocked = p_reason, revision = revision + 1
    where room_id = p_room_id;
  insert into public.moderation_events (room_id, user_id, kind, detail)
    values (p_room_id, v_state.updated_by, 'media_blocked', p_reason);
  return true;
end $$;
revoke execute on function public.reject_media(uuid, text, text) from public, anon, authenticated;

-- Called by the Edge Function with what it learned about the video
create function public.record_media_verdict(
  p_room_id uuid, p_media_key text, p_title text, p_verdict text, p_reason text
) returns boolean
language plpgsql security definer set search_path = public
as $$
declare v_term text;
begin
  if p_verdict = 'ok' then
    v_term := public.find_blocked_term(p_title);
    if v_term is not null then
      p_verdict := 'blocked';
      p_reason := 'title';
    end if;
  end if;
  insert into public.media_verdicts (media_key, title, verdict, reason)
    values (p_media_key, left(p_title, 300), p_verdict, p_reason)
    on conflict (media_key) do update
      set title = excluded.title, verdict = excluded.verdict, reason = excluded.reason, checked_at = now();
  if p_verdict = 'blocked' then
    return public.reject_media(p_room_id, p_media_key, p_reason);
  end if;
  return false;
end $$;
revoke execute on function public.record_media_verdict(uuid, text, text, text, text) from public, anon, authenticated;

-- After a video is set in an open room: use a known verdict, or ask the Edge Function to look it up
create function public.request_media_check() returns trigger
language plpgsql security definer set search_path = public
as $$
declare
  v_key text;
  v_visibility text;
  v_cached public.media_verdicts;
  v_secret text;
begin
  if new.media is null or new.media is not distinct from old.media then
    return new;
  end if;
  select visibility into v_visibility from public.rooms where id = new.room_id;
  if v_visibility is distinct from 'public' then
    return new;
  end if;

  v_key := public.media_key_of(new.media);
  select * into v_cached from public.media_verdicts where media_key = v_key and checked_at > now() - interval '7 days';
  if v_cached.media_key is not null then
    if v_cached.verdict = 'blocked' then
      perform public.reject_media(new.room_id, v_key, v_cached.reason);
    end if;
    return new;
  end if;

  if to_regnamespace('net') is not null and to_regclass('vault.decrypted_secrets') is not null then
    select decrypted_secret into v_secret from vault.decrypted_secrets where name = 'cleanup_secret';
    perform net.http_post(
      url := 'https://dmpmwcxohniwfczkoxkk.supabase.co/functions/v1/moderate-media',
      headers := jsonb_build_object('content-type', 'application/json', 'x-cleanup-secret', coalesce(v_secret, '')),
      body := jsonb_build_object(
        'roomId', new.room_id, 'type', new.media ->> 'type', 'sourceId', new.media ->> 'sourceId',
        'url', new.media ->> 'canonicalUrl'
      )
    );
  end if;
  return new;
end $$;
create trigger playback_state_request_media_check after update of media on public.playback_state
  for each row execute function public.request_media_check();

-- Three removed videos within 24 hours: no changing videos in open rooms until the strikes age out
create or replace function public.validate_playback_media() returns trigger
language plpgsql security definer set search_path = public
as $$
declare
  v_url text := coalesce(new.media ->> 'canonicalUrl', '');
  v_id text := coalesce(new.media ->> 'sourceId', '');
  v_type text := new.media ->> 'type';
  v_visibility text;
  v_ok boolean;
begin
  if new.media is null then
    return new;
  end if;

  if char_length(v_url) > 2048 or char_length(v_id) > 512 or v_url ~ '\s'
     or not public.is_clean_text(v_url) or not public.is_clean_text(v_id) then
    raise exception 'MEDIA_UNSUPPORTED';
  end if;

  v_ok := case v_type
    when 'youtube' then v_url ~ '^https://www\.youtube\.com/watch\?v=[A-Za-z0-9_-]{11}$'
                        and v_id = substring(v_url from 'v=([A-Za-z0-9_-]{11})$')
    when 'vk' then v_url ~ '^https://(vk\.com|vkvideo\.ru)/video_ext\.php\?oid=-?[0-9]+&id=[0-9]+(&hash=[A-Za-z0-9]+)?&autoplay=0$'
    when 'rutube' then v_url ~ '^https://rutube\.ru/play/embed/[a-f0-9]{32}(\?p=[A-Za-z0-9%_.~-]+)?$'
    when 'vimeo' then v_url ~ '^https://player\.vimeo\.com/video/[0-9]+(\?h=[a-f0-9]+)?$'
    when 'html5' then v_url ~* '^https?://[^/]+/'
    when 'hls' then v_url ~* '^https?://[^/]+/'
    else false
  end;
  if not coalesce(v_ok, false) then
    raise exception 'MEDIA_UNSUPPORTED';
  end if;

  select visibility into v_visibility from public.rooms where id = new.room_id;
  if v_visibility = 'public' then
    if v_type in ('html5', 'hls') and public.open_rooms_platforms_only() then
      raise exception 'MEDIA_NOT_ALLOWED_IN_OPEN_ROOM';
    end if;
    if tg_op = 'UPDATE' and new.media is distinct from old.media and new.updated_by is not null
       and (select count(*) from public.moderation_events
            where user_id = new.updated_by and kind = 'media_blocked' and created_at > now() - interval '24 hours') >= 3 then
      raise exception 'MEDIA_COOLDOWN';
    end if;
  end if;
  return new;
end $$;

-- ===== 20261022003200_media_check_unknown_not_cached.sql =====
-- An 'unknown' answer (the platform could not be read) must be asked again, not remembered.
create or replace function public.request_media_check() returns trigger
language plpgsql security definer set search_path = public
as $$
declare
  v_key text;
  v_visibility text;
  v_cached public.media_verdicts;
  v_secret text;
begin
  if new.media is null or new.media is not distinct from old.media then
    return new;
  end if;
  select visibility into v_visibility from public.rooms where id = new.room_id;
  if v_visibility is distinct from 'public' then
    return new;
  end if;

  v_key := public.media_key_of(new.media);
  select * into v_cached from public.media_verdicts where media_key = v_key and verdict in ('ok', 'blocked') and checked_at > now() - interval '7 days';
  if v_cached.media_key is not null then
    if v_cached.verdict = 'blocked' then
      perform public.reject_media(new.room_id, v_key, v_cached.reason);
    end if;
    return new;
  end if;

  if to_regnamespace('net') is not null and to_regclass('vault.decrypted_secrets') is not null then
    select decrypted_secret into v_secret from vault.decrypted_secrets where name = 'cleanup_secret';
    perform net.http_post(
      url := 'https://dmpmwcxohniwfczkoxkk.supabase.co/functions/v1/moderate-media',
      headers := jsonb_build_object('content-type', 'application/json', 'x-cleanup-secret', coalesce(v_secret, '')),
      body := jsonb_build_object(
        'roomId', new.room_id, 'type', new.media ->> 'type', 'sourceId', new.media ->> 'sourceId',
        'url', new.media ->> 'canonicalUrl'
      )
    );
  end if;
  return new;
end $$;

-- ===== 20261022003300_no_direct_media.sql =====
-- Direct files and streams (any site, or private uploads) are no longer supported in any room: nobody can see or
-- moderate what they contain. Only YouTube, VK Video, RuTube and Vimeo remain, which age-gate and moderate
-- their own videos. (The switch is a function so that tests, which play simple direct links, can turn it on.)

create function public.direct_media_allowed() returns boolean
language sql immutable
as $$ select false $$;

-- Stop whatever direct video is playing now
update public.playback_state
  set media = null, status = 'paused', anchor_position = 0, anchor_server_time = public.server_time_ms(),
      revision = revision + 1, buffering = '{}'::jsonb, resume_after_buffer = false
  where media ->> 'type' in ('html5', 'hls');

create or replace function public.validate_playback_media() returns trigger
language plpgsql security definer set search_path = public
as $$
declare
  v_url text := coalesce(new.media ->> 'canonicalUrl', '');
  v_id text := coalesce(new.media ->> 'sourceId', '');
  v_type text := new.media ->> 'type';
  v_visibility text;
  v_ok boolean;
begin
  if new.media is null then
    return new;
  end if;

  if char_length(v_url) > 2048 or char_length(v_id) > 512 or v_url ~ '\s'
     or not public.is_clean_text(v_url) or not public.is_clean_text(v_id) then
    raise exception 'MEDIA_UNSUPPORTED';
  end if;

  if v_type in ('html5', 'hls') and not public.direct_media_allowed() then
    raise exception 'MEDIA_UNSUPPORTED';
  end if;

  v_ok := case v_type
    when 'youtube' then v_url ~ '^https://www\.youtube\.com/watch\?v=[A-Za-z0-9_-]{11}$'
                        and v_id = substring(v_url from 'v=([A-Za-z0-9_-]{11})$')
    when 'vk' then v_url ~ '^https://(vk\.com|vkvideo\.ru)/video_ext\.php\?oid=-?[0-9]+&id=[0-9]+(&hash=[A-Za-z0-9]+)?&autoplay=0$'
    when 'rutube' then v_url ~ '^https://rutube\.ru/play/embed/[a-f0-9]{32}(\?p=[A-Za-z0-9%_.~-]+)?$'
    when 'vimeo' then v_url ~ '^https://player\.vimeo\.com/video/[0-9]+(\?h=[a-f0-9]+)?$'
    when 'html5' then v_url ~* '^https?://[^/]+/'
    when 'hls' then v_url ~* '^https?://[^/]+/'
    else false
  end;
  if not coalesce(v_ok, false) then
    raise exception 'MEDIA_UNSUPPORTED';
  end if;

  select visibility into v_visibility from public.rooms where id = new.room_id;
  if v_visibility = 'public' then
    if tg_op = 'UPDATE' and new.media is distinct from old.media and new.updated_by is not null
       and (select count(*) from public.moderation_events
            where user_id = new.updated_by and kind = 'media_blocked' and created_at > now() - interval '24 hours') >= 3 then
      raise exception 'MEDIA_COOLDOWN';
    end if;
  end if;
  return new;
end $$;

-- ===== 20261022003400_feed_reports_chat_links.sql =====
-- Public rooms feed, reports, and a link filter for chat in open rooms.

alter table public.rooms add column feed_hidden_until timestamptz;

-- ---------------------------------------------------------------------------
-- Feed: open rooms with someone inside and a video on. Names and chat are never shown.
-- ---------------------------------------------------------------------------
create function public.list_public_rooms(p_limit integer default 24) returns jsonb
language plpgsql security definer set search_path = public
as $$
declare
  v_uid uuid := public.require_uid();
  v_result jsonb;
begin
  perform public.check_rate(v_uid, 'feed', 30, interval '1 minute');
  select coalesce(jsonb_agg(row_to_json(x)::jsonb order by x."participantCount" desc, x."updatedAt" desc), '[]'::jsonb)
  into v_result
  from (
    select
      r.global_id as "globalId",
      public.active_seat_count(r.id) as "participantCount",
      r.max_participants as "maxParticipants",
      p.status as "status",
      p.media ->> 'type' as "mediaType",
      p.media ->> 'sourceId' as "mediaSourceId",
      (select v.title from public.media_verdicts v where v.media_key = public.media_key_of(p.media)) as "mediaTitle",
      greatest(r.updated_at, to_timestamp(p.anchor_server_time / 1000.0)) as "updatedAt"
    from public.rooms r
    join public.playback_state p on p.room_id = r.id
    where r.status = 'active'
      and r.visibility = 'public'
      and p.media is not null
      and (r.feed_hidden_until is null or r.feed_hidden_until < now())
      and public.active_seat_count(r.id) > 0
      and public.active_seat_count(r.id) < r.max_participants
      and not public.is_banned(r.id, v_uid)
    order by 3 desc
    limit least(greatest(coalesce(p_limit, 24), 1), 50)
  ) x;
  return v_result;
end $$;
revoke execute on function public.list_public_rooms(integer) from public, anon;
grant execute on function public.list_public_rooms(integer) to authenticated;

-- ---------------------------------------------------------------------------
-- Reports
-- ---------------------------------------------------------------------------
create table public.reports (
  id bigserial primary key,
  room_id uuid not null references public.rooms (id) on delete cascade,
  reporter_id uuid references public.profiles (id) on delete set null,
  message_id uuid,
  reason text not null,
  created_at timestamptz not null default now()
);
create index reports_room_idx on public.reports (room_id, created_at desc);
alter table public.reports enable row level security;
revoke all on public.reports from anon, authenticated;

-- A participant reports the room (or one chat message). Three different people reporting an open room within
-- a day take it off the feed for a day.
create function public.report_room(p_room_id uuid, p_reason text, p_message_id uuid default null) returns jsonb
language plpgsql security definer set search_path = public
as $$
declare
  v_uid uuid := public.require_uid();
  v_reason text := trim(coalesce(p_reason, ''));
  v_visibility text;
  v_reporters integer;
begin
  perform public.assert_active_member(p_room_id, v_uid);
  perform public.check_rate(v_uid, 'report', 10, interval '1 hour');
  if char_length(v_reason) < 3 or char_length(v_reason) > 500 or not public.is_clean_text(v_reason) then
    raise exception 'INVALID_PAYLOAD';
  end if;
  if p_message_id is not null
     and not exists (select 1 from public.chat_messages where id = p_message_id and room_id = p_room_id) then
    raise exception 'INVALID_PAYLOAD';
  end if;

  if not exists (
    select 1 from public.reports
    where room_id = p_room_id and reporter_id = v_uid and message_id is not distinct from p_message_id
      and created_at > now() - interval '24 hours'
  ) then
    insert into public.reports (room_id, reporter_id, message_id, reason) values (p_room_id, v_uid, p_message_id, v_reason);
  end if;

  select visibility into v_visibility from public.rooms where id = p_room_id;
  select count(distinct reporter_id) into v_reporters
    from public.reports where room_id = p_room_id and created_at > now() - interval '24 hours';
  if v_visibility = 'public' and v_reporters >= 3 then
    update public.rooms set feed_hidden_until = now() + interval '24 hours' where id = p_room_id
      and (feed_hidden_until is null or feed_hidden_until < now());
    insert into public.moderation_events (room_id, user_id, kind, detail)
      values (p_room_id, null, 'room_hidden_from_feed', v_reporters || ' reports');
  end if;
  return jsonb_build_object('ok', true);
end $$;
revoke execute on function public.report_room(uuid, text, uuid) from public, anon;
grant execute on function public.report_room(uuid, text, uuid) to authenticated;

-- ---------------------------------------------------------------------------
-- Links in the chat of open rooms: only the owner and people who may control the room can post them
-- ---------------------------------------------------------------------------
create or replace function public.validate_chat_message() returns trigger
language plpgsql security definer set search_path = public
as $$
begin
  if not public.is_clean_text(new.body) or not public.is_clean_text(new.sender_name) then
    raise exception 'INVALID_PAYLOAD';
  end if;
  if new.body ~* '(https?://|www\.|[a-z0-9-]+\.(com|ru|net|org|io|me|to|xyz|live|tv|gg|info|site|online|link)([/?#]|$|\s))'
     and exists (select 1 from public.rooms where id = new.room_id and visibility = 'public')
     and not public.can_control_playback(new.room_id, new.sender_id) then
    raise exception 'LINKS_NOT_ALLOWED';
  end if;
  return new;
end $$;

-- ===== 20261022003500_verdict_display_title.sql =====
-- The text checked against the blocked terms includes the author and description; what is stored (and shown in the
-- feed) is just the title.
drop function if exists public.record_media_verdict(uuid, text, text, text, text);
create or replace function public.record_media_verdict(
  p_room_id uuid, p_media_key text, p_title text, p_verdict text, p_reason text, p_display_title text default null
) returns boolean
language plpgsql security definer set search_path = public
as $$
declare v_term text;
begin
  if p_verdict = 'ok' then
    v_term := public.find_blocked_term(p_title);
    if v_term is not null then
      p_verdict := 'blocked';
      p_reason := 'title';
    end if;
  end if;
  insert into public.media_verdicts (media_key, title, verdict, reason)
    values (p_media_key, left(coalesce(nullif(trim(p_display_title), ''), p_title), 300), p_verdict, p_reason)
    on conflict (media_key) do update
      set title = excluded.title, verdict = excluded.verdict, reason = excluded.reason, checked_at = now();
  if p_verdict = 'blocked' then
    return public.reject_media(p_room_id, p_media_key, p_reason);
  end if;
  return false;
end $$;
revoke execute on function public.record_media_verdict(uuid, text, text, text, text, text) from public, anon, authenticated;

-- ===== 20261022003600_recommendations.sql =====
-- Recommendations: the home page offers open rooms that are being watched right now, with the video title,
-- number of participants and a banner image. Replaces list_public_rooms.
--
-- Ranking (light, explainable):
--   score = 2 per participant (up to 8) + 3 while the video is playing + up to 3 for fresh activity (fading over
--           30 minutes) + 5 if a friend of the viewer is inside + a gentle 0..1 rotation that changes every hour,
--           so the same room is not always first.
-- Rooms the viewer is already in, rooms of owners who banned the viewer, rooms hidden by reports, full rooms,
-- empty rooms and rooms without a video are left out. Names of people and chat are never included.

alter table public.media_verdicts add column thumbnail_url text;

drop function if exists public.record_media_verdict(uuid, text, text, text, text, text);
create function public.record_media_verdict(
  p_room_id uuid, p_media_key text, p_title text, p_verdict text, p_reason text,
  p_display_title text default null, p_thumbnail_url text default null
) returns boolean
language plpgsql security definer set search_path = public
as $$
declare v_term text;
begin
  if p_verdict = 'ok' then
    v_term := public.find_blocked_term(p_title);
    if v_term is not null then
      p_verdict := 'blocked';
      p_reason := 'title';
    end if;
  end if;
  -- Only plain https addresses are kept as banners
  if p_thumbnail_url is not null and (p_thumbnail_url !~ '^https://[^\s]+$' or char_length(p_thumbnail_url) > 500
                                      or not public.is_clean_text(p_thumbnail_url)) then
    p_thumbnail_url := null;
  end if;
  insert into public.media_verdicts (media_key, title, verdict, reason, thumbnail_url)
    values (p_media_key, left(coalesce(nullif(trim(p_display_title), ''), p_title), 300), p_verdict, p_reason, p_thumbnail_url)
    on conflict (media_key) do update
      set title = excluded.title, verdict = excluded.verdict, reason = excluded.reason,
          thumbnail_url = excluded.thumbnail_url, checked_at = now();
  if p_verdict = 'blocked' then
    return public.reject_media(p_room_id, p_media_key, p_reason);
  end if;
  return false;
end $$;
revoke execute on function public.record_media_verdict(uuid, text, text, text, text, text, text) from public, anon, authenticated;

drop function if exists public.list_public_rooms(integer);

create function public.get_recommendations(p_limit integer default 12) returns jsonb
language plpgsql security definer set search_path = public
as $$
declare
  v_uid uuid := public.require_uid();
  v_result jsonb;
begin
  perform public.check_rate(v_uid, 'recommendations', 30, interval '1 minute');
  select coalesce(jsonb_agg(to_jsonb(x) - 'score' order by x.score desc), '[]'::jsonb)
  into v_result
  from (
    select
      r.global_id as "globalId",
      coalesce(v.title, case p.media ->> 'type' when 'youtube' then 'YouTube' when 'vk' then 'VK Video'
                          when 'rutube' then 'RuTube' when 'vimeo' then 'Vimeo' end) as "title",
      (v.title is not null) as "hasTitle",
      s.seats as "participantCount",
      r.max_participants as "maxParticipants",
      p.media ->> 'type' as "platform",
      coalesce(v.thumbnail_url,
               case when p.media ->> 'type' = 'youtube' then 'https://i.ytimg.com/vi/' || (p.media ->> 'sourceId') || '/hqdefault.jpg' end
      ) as "thumbnailUrl",
      p.status as "status",
      s.friends as "friendsInside",
      case when s.friends > 0 then 'friends'
           when p.status = 'playing' and s.seats >= 3 then 'popular'
           when p.status = 'playing' then 'live' end as "badge",
      least(s.seats, 8) * 2.0
        + case when p.status = 'playing' then 3 else 0 end
        + greatest(0, 3 - extract(epoch from (now() - greatest(r.updated_at, to_timestamp(p.anchor_server_time / 1000.0)))) / 600.0)
        + case when s.friends > 0 then 5 else 0 end
        + (abs(hashtext(r.id::text || to_char(now(), 'YYYYMMDDHH24'))) % 100) / 100.0 as score
    from public.rooms r
    join public.playback_state p on p.room_id = r.id
    cross join lateral (
      select count(*)::int as seats,
             count(f.friend_id)::int as friends
      from public.member_activity a
      left join public.friendships f on f.user_id = v_uid and f.friend_id = a.user_id
      where a.room_id = r.id and a.last_active_at > public.seat_active_cutoff()
    ) s
    left join public.media_verdicts v on v.media_key = public.media_key_of(p.media) and v.verdict = 'ok'
    where r.status = 'active'
      and r.visibility = 'public'
      and p.media is not null
      and (r.feed_hidden_until is null or r.feed_hidden_until < now())
      and s.seats > 0
      and s.seats < r.max_participants
      and not public.is_banned(r.id, v_uid)
      and not exists (select 1 from public.room_members m where m.room_id = r.id and m.user_id = v_uid)
    order by score desc
    limit least(greatest(coalesce(p_limit, 12), 1), 30)
  ) x;
  return v_result;
end $$;
revoke execute on function public.get_recommendations(integer) from public, anon;
grant execute on function public.get_recommendations(integer) to authenticated;

-- ===== 20261022003700_recommendations_owner_and_alias.sql =====
-- Recommendations: adds ownerName to recommendations and re-establishes list_public_rooms as an alias to get_recommendations.

drop function if exists public.get_recommendations(integer);

create function public.get_recommendations(p_limit integer default 12) returns jsonb
language plpgsql security definer set search_path = public
as $$
declare
  v_uid uuid := public.require_uid();
  v_result jsonb;
begin
  perform public.check_rate(v_uid, 'recommendations', 30, interval '1 minute');
  select coalesce(jsonb_agg(to_jsonb(x) - 'score' order by x.score desc), '[]'::jsonb)
  into v_result
  from (
    select
      r.global_id as "globalId",
      coalesce(v.title, case p.media ->> 'type' when 'youtube' then 'YouTube' when 'vk' then 'VK Video'
                          when 'rutube' then 'RuTube' when 'vimeo' then 'Vimeo' end) as "title",
      (v.title is not null) as "hasTitle",
      s.seats as "participantCount",
      r.max_participants as "maxParticipants",
      p.media ->> 'type' as "platform",
      coalesce(v.thumbnail_url,
               case when p.media ->> 'type' = 'youtube' then 'https://i.ytimg.com/vi/' || (p.media ->> 'sourceId') || '/hqdefault.jpg' end
      ) as "thumbnailUrl",
      owner_p.display_name as "ownerName",
      p.status as "status",
      s.friends as "friendsInside",
      case when s.friends > 0 then 'friends'
           when p.status = 'playing' and s.seats >= 3 then 'popular'
           when p.status = 'playing' then 'live' end as "badge",
      least(s.seats, 8) * 2.0
        + case when p.status = 'playing' then 3 else 0 end
        + greatest(0, 3 - extract(epoch from (now() - greatest(r.updated_at, to_timestamp(p.anchor_server_time / 1000.0)))) / 600.0)
        + case when s.friends > 0 then 6 else 0 end
        + (abs(hashtext(r.id::text || to_char(now(), 'YYYYMMDDHH24'))) % 100) / 100.0 as score
    from public.rooms r
    join public.profiles owner_p on owner_p.id = r.owner_id
    join public.playback_state p on p.room_id = r.id
    cross join lateral (
      select count(*)::int as seats,
             count(f.friend_id)::int as friends
      from public.member_activity a
      left join public.friendships f on f.user_id = v_uid and f.friend_id = a.user_id
      where a.room_id = r.id and a.last_active_at > public.seat_active_cutoff()
    ) s
    left join public.media_verdicts v on v.media_key = public.media_key_of(p.media) and v.verdict = 'ok'
    where r.status = 'active'
      and r.visibility = 'public'
      and p.media is not null
      and (r.feed_hidden_until is null or r.feed_hidden_until < now())
      and s.seats > 0
      and s.seats < r.max_participants
      and not public.is_banned(r.id, v_uid)
      and not exists (select 1 from public.room_members m where m.room_id = r.id and m.user_id = v_uid)
    order by score desc
    limit least(greatest(coalesce(p_limit, 12), 1), 30)
  ) x;
  return v_result;
end $$;
revoke execute on function public.get_recommendations(integer) from public, anon;
grant execute on function public.get_recommendations(integer) to authenticated;

create or replace function public.list_public_rooms(p_limit integer default 24) returns jsonb
language sql security definer set search_path = public
as $$
  select public.get_recommendations(p_limit);
$$;
revoke execute on function public.list_public_rooms(integer) from public, anon;
grant execute on function public.list_public_rooms(integer) to authenticated;

-- ===== 20261022003800_fix_room_mutes_in_everyone_mode.sql =====
-- Fix room mutes in 'everyone' mode:
-- In 'everyone' mode, ordinary participants can control playback, but they are not controllers.
-- The owner (and appointed controllers) must be able to mute ordinary members in 'everyone' mode.

create or replace function public.set_member_muted(p_room_id uuid, p_user_id uuid, p_muted boolean) returns void
language plpgsql security definer set search_path = public
as $$
declare v_uid uuid := public.require_uid();
begin
  perform public.assert_active_member(p_room_id, v_uid);
  -- Only the owner or members explicitly granted control may mute others
  if not exists (
    select 1 from public.room_members
    where room_id = p_room_id and user_id = v_uid and (role = 'owner' or can_control = true)
  ) then
    raise exception 'FORBIDDEN';
  end if;

  if p_user_id is null or p_user_id = v_uid
     or not exists (select 1 from public.room_members where room_id = p_room_id and user_id = p_user_id) then
    raise exception 'INVALID_PAYLOAD';
  end if;

  if coalesce(p_muted, false) then
    -- The owner and members explicitly granted control cannot be muted
    if exists (
      select 1 from public.room_members
      where room_id = p_room_id and user_id = p_user_id and (role = 'owner' or can_control = true)
    ) then
      raise exception 'FORBIDDEN';
    end if;
    insert into public.room_mutes (room_id, user_id, muted_by) values (p_room_id, p_user_id, v_uid)
      on conflict (room_id, user_id) do nothing;
  else
    delete from public.room_mutes where room_id = p_room_id and user_id = p_user_id;
  end if;
end $$;

revoke execute on function public.set_member_muted(uuid, uuid, boolean) from public, anon;
grant execute on function public.set_member_muted(uuid, uuid, boolean) to authenticated;

-- ===== 20261022003900_chat_reactions_and_deletion.sql =====
-- Migration: Add chat message reactions and message deletion
-- Allows active room members to react to messages with emojis
-- and allows sender / owner / controllers to delete messages.

alter table public.chat_messages add column if not exists reactions jsonb not null default '{}'::jsonb;

-- Toggle emoji reaction on a chat message
create or replace function public.toggle_chat_reaction(
  p_room_id uuid,
  p_message_id uuid,
  p_emoji text
) returns jsonb
language plpgsql
security definer
set search_path = public, pg_temp as $$
declare
  v_uid uuid := public.require_uid();
  v_reactions jsonb;
  v_arr jsonb;
  v_new_arr jsonb;
  v_emoji text := trim(coalesce(p_emoji, ''));
begin
  perform public.assert_active_member(p_room_id, v_uid);
  perform public.check_rate(v_uid, 'chat_reaction', 40, interval '10 seconds');

  if char_length(v_emoji) > 8 or v_emoji = '' then
    raise exception 'INVALID_PAYLOAD';
  end if;

  select reactions into v_reactions
  from public.chat_messages
  where id = p_message_id and room_id = p_room_id
  for update;

  if not found then
    raise exception 'NOT_FOUND';
  end if;

  v_reactions := coalesce(v_reactions, '{}'::jsonb);
  v_arr := coalesce(v_reactions -> v_emoji, '[]'::jsonb);

  if jsonb_path_exists(v_arr, ('$[*] ? (@ == "' || v_uid::text || '")')::jsonpath) then
    -- Remove reaction
    select coalesce(jsonb_agg(elem), '[]'::jsonb) into v_new_arr
    from jsonb_array_elements_text(v_arr) elem
    where elem <> v_uid::text;

    if jsonb_array_length(v_new_arr) = 0 then
      v_reactions := v_reactions - v_emoji;
    else
      v_reactions := jsonb_set(v_reactions, array[v_emoji], v_new_arr);
    end if;
  else
    -- Add reaction
    v_new_arr := v_arr || to_jsonb(v_uid::text);
    v_reactions := jsonb_set(v_reactions, array[v_emoji], v_new_arr);
  end if;

  update public.chat_messages
  set reactions = v_reactions
  where id = p_message_id and room_id = p_room_id;

  return v_reactions;
end $$;

revoke execute on function public.toggle_chat_reaction(uuid, uuid, text) from public, anon;
grant execute on function public.toggle_chat_reaction(uuid, uuid, text) to authenticated;

-- Delete a chat message (allowed by sender, room owner, or controllers)
create or replace function public.delete_chat_message(
  p_room_id uuid,
  p_message_id uuid
) returns boolean
language plpgsql
security definer
set search_path = public, pg_temp as $$
declare
  v_uid uuid := public.require_uid();
  v_msg public.chat_messages;
begin
  perform public.assert_active_member(p_room_id, v_uid);

  select * into v_msg
  from public.chat_messages
  where id = p_message_id and room_id = p_room_id;

  if not found then
    return false;
  end if;

  if v_msg.sender_id <> v_uid
     and v_uid <> (select owner_id from public.rooms where id = p_room_id)
     and not exists (
       select 1 from public.room_members
       where room_id = p_room_id and user_id = v_uid and (role = 'owner' or can_control = true)
     ) then
    raise exception 'FORBIDDEN';
  end if;

  delete from public.chat_messages
  where id = p_message_id and room_id = p_room_id;

  return true;
end $$;

revoke execute on function public.delete_chat_message(uuid, uuid) from public, anon;
grant execute on function public.delete_chat_message(uuid, uuid) to authenticated;

-- ===== 20261022004000_add_kodik_media.sql =====
-- Adds Kodik media platform support (movies, series, anime with HDRezka voiceovers)

create or replace function public.validate_playback_media() returns trigger
language plpgsql security definer set search_path = public
as $$
declare
  v_url text := coalesce(new.media ->> 'canonicalUrl', '');
  v_id text := coalesce(new.media ->> 'sourceId', '');
  v_type text := new.media ->> 'type';
  v_visibility text;
  v_ok boolean;
begin
  if new.media is null then
    return new;
  end if;

  if char_length(v_url) > 2048 or char_length(v_id) > 512 or v_url ~ '\s'
     or not public.is_clean_text(v_url) or not public.is_clean_text(v_id) then
    raise exception 'MEDIA_UNSUPPORTED';
  end if;

  if v_type in ('html5', 'hls') and not public.direct_media_allowed() then
    raise exception 'MEDIA_UNSUPPORTED';
  end if;

  v_ok := case v_type
    when 'youtube' then v_url ~ '^https://www\.youtube\.com/watch\?v=[A-Za-z0-9_-]{11}$'
                        and v_id = substring(v_url from 'v=([A-Za-z0-9_-]{11})$')
    when 'vk' then v_url ~ '^https://(vk\.com|vkvideo\.ru)/video_ext\.php\?oid=-?[0-9]+&id=[0-9]+(&hash=[A-Za-z0-9]+)?&autoplay=0$'
    when 'rutube' then v_url ~ '^https://rutube\.ru/play/embed/[a-f0-9]{32}(\?p=[A-Za-z0-9%_.~-]+)?$'
    when 'vimeo' then v_url ~ '^https://player\.vimeo\.com/video/[0-9]+(\?h=[a-f0-9]+)?$'
    when 'kodik' then v_url ~* '^https://([a-zA-Z0-9-]+\.)*(kodik\.info|kodikplayer\.com|aniqit\.com|anivod\.com|kodik\.biz|kodik\.cc)/(video|seria|serial)/[0-9]+/[a-zA-Z0-9]+(/[a-zA-Z0-9]+)?(\?[^#\s]*)?$'
    when 'html5' then v_url ~* '^https?://[^/]+/'
    when 'hls' then v_url ~* '^https?://[^/]+/'
    else false
  end;
  if not coalesce(v_ok, false) then
    raise exception 'MEDIA_UNSUPPORTED';
  end if;

  select visibility into v_visibility from public.rooms where id = new.room_id;
  if v_visibility = 'public' then
    if tg_op = 'UPDATE' and new.media is distinct from old.media and new.updated_by is not null
       and (select count(*) from public.moderation_events
            where user_id = new.updated_by and kind = 'media_blocked' and created_at > now() - interval '24 hours') >= 3 then
      raise exception 'MEDIA_COOLDOWN';
    end if;
  end if;
  return new;
end $$;

create or replace function public.get_recommendations(p_limit integer default 12) returns jsonb
language plpgsql security definer set search_path = public
as $$
declare
  v_uid uuid := public.require_uid();
  v_result jsonb;
begin
  perform public.check_rate(v_uid, 'recommendations', 30, interval '1 minute');
  select coalesce(jsonb_agg(to_jsonb(x) - 'score' order by x.score desc), '[]'::jsonb)
  into v_result
  from (
    select
      r.global_id as "globalId",
      coalesce(v.title, case p.media ->> 'type' when 'youtube' then 'YouTube' when 'vk' then 'VK Video'
                          when 'rutube' then 'RuTube' when 'vimeo' then 'Vimeo' when 'kodik' then 'Кино (Kodik)' end) as "title",
      (v.title is not null) as "hasTitle",
      s.seats as "participantCount",
      r.max_participants as "maxParticipants",
      p.media ->> 'type' as "platform",
      coalesce(v.thumbnail_url,
               case when p.media ->> 'type' = 'youtube' then 'https://i.ytimg.com/vi/' || (p.media ->> 'sourceId') || '/hqdefault.jpg' end
      ) as "thumbnailUrl",
      owner_p.display_name as "ownerName",
      p.status as "status",
      s.friends as "friendsInside",
      case when s.friends > 0 then 'friends'
           when p.status = 'playing' and s.seats >= 3 then 'popular'
           when p.status = 'playing' then 'live' end as "badge",
      least(s.seats, 8) * 2.0
        + case when p.status = 'playing' then 3 else 0 end
        + greatest(0, 3 - extract(epoch from (now() - greatest(r.updated_at, to_timestamp(p.anchor_server_time / 1000.0)))) / 600.0)
        + case when s.friends > 0 then 6 else 0 end
        + (abs(hashtext(r.id::text || to_char(now(), 'YYYYMMDDHH24'))) % 100) / 100.0 as score
    from public.rooms r
    join public.profiles owner_p on owner_p.id = r.owner_id
    join public.playback_state p on p.room_id = r.id
    cross join lateral (
      select count(*)::int as seats,
             count(f.friend_id)::int as friends
      from public.member_activity a
      left join public.friendships f on f.user_id = v_uid and f.friend_id = a.user_id
      where a.room_id = r.id and a.last_active_at > public.seat_active_cutoff()
    ) s
    left join public.media_verdicts v on v.media_key = public.media_key_of(p.media) and v.verdict = 'ok'
    where r.status = 'active'
      and r.visibility = 'public'
      and p.media is not null
      and (r.feed_hidden_until is null or r.feed_hidden_until < now())
      and s.seats > 0
      and s.seats < r.max_participants
      and not public.is_banned(r.id, v_uid)
      and not exists (select 1 from public.room_members m where m.room_id = r.id and m.user_id = v_uid)
    order by score desc
    limit least(greatest(coalesce(p_limit, 12), 1), 30)
  ) x;
  return v_result;
end $$;
revoke execute on function public.get_recommendations(integer) from public, anon;
grant execute on function public.get_recommendations(integer) to authenticated;

-- ===== 20261022004100_allow_direct_media_for_mar.sql =====
-- Allows direct media (HTML5 MP4/WebM and HLS streams) specifically for user 'Mar' (or rooms owned by 'Mar')

create or replace function public.validate_playback_media() returns trigger
language plpgsql security definer set search_path = public
as $$
declare
  v_url text := coalesce(new.media ->> 'canonicalUrl', '');
  v_id text := coalesce(new.media ->> 'sourceId', '');
  v_type text := new.media ->> 'type';
  v_visibility text;
  v_ok boolean;
begin
  if new.media is null then
    return new;
  end if;

  if char_length(v_url) > 2048 or char_length(v_id) > 512 or v_url ~ '\s'
     or not public.is_clean_text(v_url) or not public.is_clean_text(v_id) then
    raise exception 'MEDIA_UNSUPPORTED';
  end if;

  if v_type in ('html5', 'hls') and not public.direct_media_allowed() then
    if not exists (
      select 1 from public.profiles
      where id = new.updated_by and (lower(username) = 'mar' or lower(display_name) = 'mar')
    ) and not exists (
      select 1 from public.rooms r
      join public.profiles p on p.id = r.owner_id
      where r.id = new.room_id and (lower(p.username) = 'mar' or lower(p.display_name) = 'mar')
    ) then
      raise exception 'MEDIA_UNSUPPORTED';
    end if;
  end if;

  v_ok := case v_type
    when 'youtube' then v_url ~ '^https://www\.youtube\.com/watch\?v=[A-Za-z0-9_-]{11}$'
                        and v_id = substring(v_url from 'v=([A-Za-z0-9_-]{11})$')
    when 'vk' then v_url ~ '^https://(vk\.com|vkvideo\.ru)/video_ext\.php\?oid=-?[0-9]+&id=[0-9]+(&hash=[A-Za-z0-9]+)?&autoplay=0$'
    when 'rutube' then v_url ~ '^https://rutube\.ru/play/embed/[a-f0-9]{32}(\?p=[A-Za-z0-9%_.~-]+)?$'
    when 'vimeo' then v_url ~ '^https://player\.vimeo\.com/video/[0-9]+(\?h=[a-f0-9]+)?$'
    when 'kodik' then v_url ~* '^https://([a-zA-Z0-9-]+\.)*(kodik\.info|kodikplayer\.com|aniqit\.com|anivod\.com|kodik\.biz|kodik\.cc)/(video|seria|serial)/[0-9]+/[a-zA-Z0-9]+(/[a-zA-Z0-9]+)?(\?[^#\s]*)?$'
    when 'html5' then v_url ~* '^https?://[^/]+/'
    when 'hls' then v_url ~* '^https?://[^/]+/'
    else false
  end;
  if not coalesce(v_ok, false) then
    raise exception 'MEDIA_UNSUPPORTED';
  end if;

  select visibility into v_visibility from public.rooms where id = new.room_id;
  if v_visibility = 'public' then
    if tg_op = 'UPDATE' and new.media is distinct from old.media and new.updated_by is not null
       and (select count(*) from public.moderation_events
            where user_id = new.updated_by and kind = 'media_blocked' and created_at > now() - interval '24 hours') >= 3 then
      raise exception 'MEDIA_COOLDOWN';
    end if;
  end if;
  return new;
end $$;

-- ===== 20261022004200_admin_role_and_videos.sql =====
-- Admin role + a public "videos" bucket the admin uploads full films/series into.
-- Direct media (HTML5 / HLS links, including videos from that bucket) is now gated by the admin role
-- instead of the display name "Mar", which anyone could pick for themselves.

alter table public.profiles add column role text not null default 'user' check (role in ('user', 'admin'));

-- Clients never write profiles directly (all writes go through SECURITY DEFINER RPCs that do not touch
-- role), so the role can only be granted from the SQL editor / service role. The registered account
-- with username "mar" becomes the first admin; grant others with:
--   update public.profiles set role = 'admin' where id = '<user uuid>';
update public.profiles set role = 'admin' where lower(username) = 'mar';

create function public.is_admin(p_user uuid default auth.uid()) returns boolean
language sql stable security definer set search_path = public
as $$
  select exists (select 1 from public.profiles where id = p_user and role = 'admin')
$$;
revoke execute on function public.is_admin(uuid) from public, anon;
grant execute on function public.is_admin(uuid) to authenticated;

-- The role must not be changeable through any client-reachable path, even if a policy is added later.
create function public.profiles_protect_role() returns trigger
language plpgsql set search_path = public
as $$
begin
  if new.role is distinct from old.role and auth.uid() is not null then
    raise exception 'FORBIDDEN';
  end if;
  return new;
end $$;
create trigger profiles_protect_role before update on public.profiles
  for each row execute function public.profiles_protect_role();

create or replace function public.validate_playback_media() returns trigger
language plpgsql security definer set search_path = public
as $$
declare
  v_url text := coalesce(new.media ->> 'canonicalUrl', '');
  v_id text := coalesce(new.media ->> 'sourceId', '');
  v_type text := new.media ->> 'type';
  v_visibility text;
  v_ok boolean;
begin
  if new.media is null then
    return new;
  end if;

  if char_length(v_url) > 2048 or char_length(v_id) > 512 or v_url ~ '\s'
     or not public.is_clean_text(v_url) or not public.is_clean_text(v_id) then
    raise exception 'MEDIA_UNSUPPORTED';
  end if;

  -- Only a media CHANGE needs the admin; everyone in the room may still pause/seek what the admin started.
  if v_type in ('html5', 'hls')
     and (tg_op = 'INSERT' or new.media is distinct from old.media)
     and not public.direct_media_allowed()
     and not public.is_admin(new.updated_by) then
    raise exception 'MEDIA_UNSUPPORTED';
  end if;

  v_ok := case v_type
    when 'youtube' then v_url ~ '^https://www\.youtube\.com/watch\?v=[A-Za-z0-9_-]{11}$'
                        and v_id = substring(v_url from 'v=([A-Za-z0-9_-]{11})$')
    when 'vk' then v_url ~ '^https://(vk\.com|vkvideo\.ru)/video_ext\.php\?oid=-?[0-9]+&id=[0-9]+(&hash=[A-Za-z0-9]+)?&autoplay=0$'
    when 'rutube' then v_url ~ '^https://rutube\.ru/play/embed/[a-f0-9]{32}(\?p=[A-Za-z0-9%_.~-]+)?$'
    when 'vimeo' then v_url ~ '^https://player\.vimeo\.com/video/[0-9]+(\?h=[a-f0-9]+)?$'
    when 'kodik' then v_url ~* '^https://([a-zA-Z0-9-]+\.)*(kodik\.info|kodikplayer\.com|aniqit\.com|anivod\.com|kodik\.biz|kodik\.cc)/(video|seria|serial)/[0-9]+/[a-zA-Z0-9]+(/[a-zA-Z0-9]+)?(\?[^#\s]*)?$'
    when 'html5' then v_url ~* '^https?://[^/]+/'
    when 'hls' then v_url ~* '^https?://[^/]+/'
    else false
  end;
  if not coalesce(v_ok, false) then
    raise exception 'MEDIA_UNSUPPORTED';
  end if;

  select visibility into v_visibility from public.rooms where id = new.room_id;
  if v_visibility = 'public' then
    if tg_op = 'UPDATE' and new.media is distinct from old.media and new.updated_by is not null
       and (select count(*) from public.moderation_events
            where user_id = new.updated_by and kind = 'media_blocked' and created_at > now() - interval '24 hours') >= 3 then
      raise exception 'MEDIA_COOLDOWN';
    end if;
  end if;
  return new;
end $$;

-- Storage: public-read bucket (the browser <video> tag needs Range requests / 206 without auth headers);
-- only admins may upload, replace or delete. Skipped where the Storage schema does not exist.
do $$
begin
  if to_regclass('storage.buckets') is null then
    raise notice 'storage schema not present: skipping videos bucket setup';
    return;
  end if;

  insert into storage.buckets (id, name, public, allowed_mime_types)
  values ('videos', 'videos', true, array['video/mp4', 'video/webm'])
  on conflict (id) do update
    set public = true, allowed_mime_types = array['video/mp4', 'video/webm'];

  execute $p$
    create policy videos_admin_select on storage.objects for select to authenticated
    using (bucket_id = 'videos' and public.is_admin())
  $p$;
  execute $p$
    create policy videos_admin_insert on storage.objects for insert to authenticated
    with check (bucket_id = 'videos' and public.is_admin())
  $p$;
  execute $p$
    create policy videos_admin_update on storage.objects for update to authenticated
    using (bucket_id = 'videos' and public.is_admin())
    with check (bucket_id = 'videos' and public.is_admin())
  $p$;
  execute $p$
    create policy videos_admin_delete on storage.objects for delete to authenticated
    using (bucket_id = 'videos' and public.is_admin())
  $p$;
end $$;
